        //Calculate Age from Birthdate
        public string CalculateAgeInYearsAndMonths(DateTime birthDate)
        {
            DateTime today = DateTime.Today;

            int years = today.Year - birthDate.Year;
            int months = today.Month - birthDate.Month;

            // If birthdate hasn't occurred yet this year, adjust years and months
            if (today.Day < birthDate.Day)
            {
                months--;
            }

            // Adjust if month is negative
            if (months < 0)
            {
                years--;
                months += 12;
            }

            return years.ToString() + "-" + months.ToString();
        }

        public List<FetchMutationName> GetMutationName(string applicationid)
        {
            List<FetchMutationName> list = new List<FetchMutationName>();
            List<MutationGiverTakerDTL> data = new List<MutationGiverTakerDTL>();
            data = _contextR.mutationDTL.Include(i => i.userMaster).Include(app => app.applicationDTL).Where(data => data.applicationDTL!.applicationid!.Equals(applicationid) && data.isDeleted == false).ToList()!;
            if (data != null)
            {
                foreach (var dtl in data)
                {
                    list.Add(new FetchMutationName
                    {
                        mutation_dtl_id = dtl.mutation_givertaker_id,
                        fullNameinMarathi = dtl.prefix_in_marathi + " " + dtl.fname_in_marathi + " " + dtl.mname_in_marathi + " " + dtl.lname_in_marathi,
                        fullNameinEng = dtl.prefix_in_eng + " " + dtl.fname_in_eng + " " + dtl.mname_in_eng + " " + dtl.lname_in_eng,
                    });
                }
                //Console.WriteLine("MutationDetails" + data);
            }
            return list;
        }

