        {
            TextInfo textInfo = new CultureInfo("en-US", false).TextInfo;
            MethodForFileUpload methodForFile = new MethodForFileUpload();
            var entity = _context.mutationDTL.FirstOrDefault(s => s.mutation_givertaker_id == kharediNondDataForTaker.MutationId!)!;
            if (entity != null)
            {
                using (var dbContextTransaction = _context.Database.BeginTransaction())
                {
                    try
                    {
                        string FolderPath = @"\\10.10.248.2\pde_propertycard\MUTATIONDOCS\" + kharediNondDataForTaker.applicationid + @"\TAKER";
                        // Assign Values to Model
                        KharediNondModel kharediNondModel = new KharediNondModel();
                        UserMaster userMaster = _context.userMasters.FirstOrDefault(s => s.userid == kharediNondDataForTaker.userid!)!;
                        kharediNondModel.userMaster = userMaster;

                        ApplicationDTL applicationDTL = _context.applicationDTL.FirstOrDefault(s => s.applicationid == kharediNondDataForTaker.applicationid!)!;
                        kharediNondModel.applicationDTL = applicationDTL;

                        PropertyTypeMaster proptype = _context.propertyTypes.FirstOrDefault(s => s.propertytypeid == Convert.ToInt32(kharediNondDataForTaker.isMHProperty!.propType!))!;
                        kharediNondModel.propType = proptype;

                        kharediNondModel.address_type = kharediNondDataForTaker.address!.addressType!.Trim().ToUpper();
                        if (kharediNondModel.address_type == "INDIA")
                        {
                            kharediNondModel.mobileno = kharediNondDataForTaker.address.indiaAddress!.mobile;
                            kharediNondModel.mobilenoverified = kharediNondDataForTaker.address.indiaAddress.mobileOTP;
                            kharediNondModel.emailid = "NA";
                            kharediNondModel.emailidverified = "NA";

                            kharediNondModel.address = "NA";
                            kharediNondModel.state = kharediNondDataForTaker.address.indiaAddress.state;
                            kharediNondModel.district = kharediNondDataForTaker.address.indiaAddress.district;
                            kharediNondModel.taluka = kharediNondDataForTaker.address.indiaAddress.taluka;
                            kharediNondModel.city = kharediNondDataForTaker.address.indiaAddress.city;
                            kharediNondModel.plotno = kharediNondDataForTaker.address.indiaAddress.plotNo;
