        public string EditBakshishPatraTaker(EditBakshishPatraTakerData bakshishpatraDataForTaker)
        {
            var entity = _context.mutationDTL.FirstOrDefault(s => s.mutation_givertaker_id == bakshishpatraDataForTaker.MutationId!)!;
            TextInfo textInfo = new CultureInfo("en-US", false).TextInfo;
            MethodForFileUpload methodForFile = new MethodForFileUpload();
            if (entity != null)
            {
                using (var dbContextTransaction = _context.Database.BeginTransaction())
                {
                    try
                    {
                        string FolderPath = @"\\10.10.248.2\pde_propertycard\MUTATIONDOCS\" + bakshishpatraDataForTaker.applicationid + @"\TAKER";
                        // Assign Values to Model
                        KharediNondModel kharediNondModel = new KharediNondModel();
                        UserMaster userMaster = _context.userMasters.FirstOrDefault(s => s.userid == bakshishpatraDataForTaker.userid!)!;
                        kharediNondModel.userMaster = userMaster;

                        ApplicationDTL applicationDTL = _context.applicationDTL.FirstOrDefault(s => s.applicationid == bakshishpatraDataForTaker.applicationid!)!;
                        kharediNondModel.applicationDTL = applicationDTL;

                        PropertyTypeMaster proptype = _context.propertyTypes.FirstOrDefault(s => s.propertytypeid == Convert.ToInt32(bakshishpatraDataForTaker.isMHProperty!.propType!))!;
                        kharediNondModel.propType = proptype;

                        kharediNondModel.address_type = bakshishpatraDataForTaker.address!.addressType!.Trim().ToUpper();
                        if (kharediNondModel.address_type == "INDIA")
                        {
                            kharediNondModel.mobileno = bakshishpatraDataForTaker.address.indiaAddress!.mobile;
                            kharediNondModel.mobilenoverified = bakshishpatraDataForTaker.address.indiaAddress.mobileOTP;
                            kharediNondModel.emailid = "NA";
                            kharediNondModel.emailidverified = "NA";

                            kharediNondModel.address = "NA";
                            kharediNondModel.state = bakshishpatraDataForTaker.address.indiaAddress.state;
                            kharediNondModel.district = bakshishpatraDataForTaker.address.indiaAddress.district;
                            kharediNondModel.taluka = bakshishpatraDataForTaker.address.indiaAddress.taluka;
                            kharediNondModel.city = bakshishpatraDataForTaker.address.indiaAddress.city;
                            kharediNondModel.plotno = bakshishpatraDataForTaker.address.indiaAddress.plotNo;
                            kharediNondModel.building = bakshishpatraDataForTaker.address.indiaAddress.building;
                            kharediNondModel.mainroad = bakshishpatraDataForTaker.address.indiaAddress.mainRoad;
                            kharediNondModel.impSymbol = bakshishpatraDataForTaker.address.indiaAddress.impSymbol;
                            kharediNondModel.area = bakshishpatraDataForTaker.address.indiaAddress.area;
                            kharediNondModel.pincode = bakshishpatraDataForTaker.address.indiaAddress.pincode;
                            kharediNondModel.post_office_name = bakshishpatraDataForTaker.address.indiaAddress.postOfficeName;
                        }
                        else if (kharediNondModel.address_type == "FOREIGN")
                        {
                            kharediNondModel.address = bakshishpatraDataForTaker.address.foreignAddress!.address;
                            kharediNondModel.mobileno = bakshishpatraDataForTaker.address.foreignAddress.mobile;
                            kharediNondModel.emailid = bakshishpatraDataForTaker.address.foreignAddress.email;
                            kharediNondModel.emailidverified = bakshishpatraDataForTaker.address.foreignAddress.emailOTP;

                            kharediNondModel.state = "NA";
                            kharediNondModel.district = "NA";
                            kharediNondModel.taluka = "NA";
                            kharediNondModel.city = "NA";
                            kharediNondModel.plotno = "NA";
                            kharediNondModel.building = "NA";
                            kharediNondModel.mainroad = "NA";
                            kharediNondModel.impSymbol = "NA";
                            kharediNondModel.area = "NA";
                            kharediNondModel.pincode = "NA";
                            kharediNondModel.post_office_name = "NA";
                        }

                        kharediNondModel.usertype_code = bakshishpatraDataForTaker.usertype_code;
                        kharediNondModel.usertype = bakshishpatraDataForTaker.usertype;

                        //isMHproperty
                        kharediNondModel.hasProperty = bakshishpatraDataForTaker.isMHProperty!.hasProperty;
                        // kharediNondModel.propType = bakshishpatraDataForTaker.isMHProperty.propType;
                        if (kharediNondModel.hasProperty!.Trim().ToUpper() == "YES")
                        {
                            if (kharediNondModel.propType.propertytypeid == 1 && string.IsNullOrEmpty(bakshishpatraDataForTaker.isMHProperty!.userDetails!.khataNo))
                            {
                                return "When Property Type Is 7/12 Then Khate No Should Not Be Empty";
                            }
                            if (kharediNondModel.propType.propertytypeid == 2 && string.IsNullOrEmpty(bakshishpatraDataForTaker.isMHProperty!.userDetails!.naBhu))
                            {
                                return "When Property Type Is Property Card Then City Servey No Should Not Be Empty";
                            }
                            if (kharediNondModel.propType.propertytypeid == 3 && string.IsNullOrEmpty(bakshishpatraDataForTaker.isMHProperty!.userDetails!.ulpin))
                            {
                                return "When Property Type Is ULPIN Then ULPIN Should Not Be Empty";
                            }
                            kharediNondModel.khatano = string.IsNullOrEmpty(bakshishpatraDataForTaker.isMHProperty!.userDetails!.khataNo) ? "NA" : bakshishpatraDataForTaker.isMHProperty.userDetails.khataNo;
                            kharediNondModel.city_servey_no = string.IsNullOrEmpty(bakshishpatraDataForTaker.isMHProperty.userDetails.naBhu) ? "NA" : bakshishpatraDataForTaker.isMHProperty.userDetails.naBhu;
