                            {
                                kharediNondModel.city_servey_no = "NA";
                                kharediNondModel.ulpin = "NA";
                            }
                            else if (kharediNondModel.propType.propertytypeid == 2)
                            {
                                kharediNondModel.khatano = "NA";
                                kharediNondModel.ulpin = "NA";
                            }
                            else if (kharediNondModel.propType.propertytypeid == 3)
                            {
                                kharediNondModel.khatano = "NA";
                                kharediNondModel.city_servey_no = "NA";
                            }
                            kharediNondModel.district_code = bakshishpatraDataForTaker.isMHProperty.userDetails.district!.district_code;
                            kharediNondModel.district_name_in_marathi = bakshishpatraDataForTaker.isMHProperty.userDetails.district!.district_name!;
                            kharediNondModel.district_name_in_eng = bakshishpatraDataForTaker.isMHProperty.userDetails.district!.district_english_name!;
                            kharediNondModel.office_code = bakshishpatraDataForTaker.isMHProperty.userDetails.taluka!.office_code;
