            try
            {
                //if (mutationdtlid == 756 || mutationdtlid == 762)
                //{
                //    string abc = "hello";
                //}
                MethodForFileUpload methodForFile = new MethodForFileUpload();
                MutationGiverTakerDTL BakshishPatraInformation = new MutationGiverTakerDTL();
                BakshishPatraInformation = _contextR.mutationDTL.Include(i => i.userMaster).Include(app => app.applicationDTL).Include(prop => prop.prop_type).Where(data => data.mutation_givertaker_id.Equals(mutationdtlid) && data.isDeleted == false).FirstOrDefault()!;

                FetchBakshishPatraDataForTaker fetchData = new FetchBakshishPatraDataForTaker();
                fetchData.mutation_dtl_id = BakshishPatraInformation.mutation_givertaker_id;
                fetchData.userid = BakshishPatraInformation.userMaster!.userid;
                fetchData.applicationid = BakshishPatraInformation.applicationDTL!.applicationid;
                fetchData.userType = BakshishPatraInformation.user_type;
                fetchData.usertype_code = BakshishPatraInformation.user_type_code;

                fetchData.mobileNo = BakshishPatraInformation.mobileno;

                //Photo Details
                InputDataModel.photoDetails photo = new photoDetails();
                photo.passportName = BakshishPatraInformation.profile_pic_file_name;
                photo.passportSrc = BakshishPatraInformation.profile_pic_file_path;
                //string PhotoProofExt = Path.GetExtension(BakshishPatraInformation.profile_pic_file_path)!;
                //string PhotoProof = methodForFile.ConvertImageToBase64(BakshishPatraInformation.profile_pic_file_path!);
