                    aapak.apk_code = BakshishPatraInformation.apk_code;
                    aapak.apk_description = BakshishPatraInformation.apk_description;
                    userdharak.aapakDropdown = aapak;
                    aapakRelation aapakrelation = new aapakRelation();
                    aapakrelation.relation_code = BakshishPatraInformation.relation_code.ToString();
                    aapakrelation.relation_name = BakshishPatraInformation.relation_name;
                    userdharak.aapakRelation = aapakrelation;
                    dharak.userdharak = userdharak;
                }
                else
                {
                    fetchData.fullNameInMarathi = BakshishPatraInformation.company_name_in_marathi!;
                    fetchData.fullNameInEng = BakshishPatraInformation.company_name_in_eng!;
                    InputDataModel.BakshishPatracompanydharakDetails companydharak = new BakshishPatracompanydharakDetails();
                    //companydharak.holderType = BakshishPatraInformation.holder_type;
                    /* InputDataModel.KhataType khatatype = new KhataType();
                     khatatype.khataCode = BakshishPatraInformation.khata_type_code;
                     khatatype.khataLabel = BakshishPatraInformation.khata_type_name;
                     companydharak.khataType = khatatype;*/
                    //  companydharak.aapakDropdown = BakshishPatraInformation.aapak_dropdown;
                    //companydharak.aapak = BakshishPatraInformation.aapak;
                    companydharak.landBuyArea = BakshishPatraInformation.land_buy_area;
                    companydharak.giftArea = BakshishPatraInformation.mutation_area;
                    InputDataModel.Holdertype holdertype = new InputDataModel.Holdertype();
                    holdertype.owner_status_code = BakshishPatraInformation.owner_status_code;
                    holdertype.owner_status_description = BakshishPatraInformation.owner_status_description;
                    companydharak.holderType = holdertype;
                    /*InputDataModel.aapakDropdown aapak = new InputDataModel.aapakDropdown();
                    aapak.apk_code = BakshishPatraInformation.apk_code;
                    aapak.apk_description = BakshishPatraInformation.apk_description;
                    companydharak.aapakDropdown = aapak;*/
                    dharak.companydharak = companydharak;
                }

                fetchData.dharak = dharak;

                //Address Details
                InputDataModel.AddressDTLForKharediNond addressData = new InputDataModel.AddressDTLForKharediNond();
                addressData.addressType = BakshishPatraInformation.address_type;
                if (BakshishPatraInformation.address_type == "INDIA")
                {
                    InputDataModel.IndiaAddressForKharediNond addressForIndia = new InputDataModel.IndiaAddressForKharediNond();
                    addressForIndia.state = BakshishPatraInformation.state;
                    addressForIndia.district = BakshishPatraInformation.district;
                    addressForIndia.city = BakshishPatraInformation.city;
                    addressForIndia.taluka = BakshishPatraInformation.taluka;
                    addressForIndia.plotNo = BakshishPatraInformation.flatno_plotno;
                    addressForIndia.building = BakshishPatraInformation.societyname;
                    addressForIndia.mainRoad = BakshishPatraInformation.mainstreet;
                    addressForIndia.impSymbol = BakshishPatraInformation.landmark;
                    addressForIndia.area = BakshishPatraInformation.locality;
                    addressForIndia.pincode = BakshishPatraInformation.pincode;
                    addressForIndia.postOfficeName = BakshishPatraInformation.post_office_name;
                    addressForIndia.addressProofName = BakshishPatraInformation.address_proof_document_name;
                    addressForIndia.mobile = BakshishPatraInformation.mobileno;
                    addressForIndia.mobileOTP = BakshishPatraInformation.mobilenoverified;
                    addressForIndia.signatureName = BakshishPatraInformation.signed_file_name!;

                    if (BakshishPatraInformation.address_proof_document_path != "NA")
                    {
                        string AddressProofExt = Path.GetExtension(BakshishPatraInformation.address_proof_document_path)!;
                        string AddressProof = methodForFile.ConvertImageToBase64(BakshishPatraInformation.address_proof_document_path!);
                        BakshishPatraInformation.address_proof_document_path = string.IsNullOrEmpty(AddressProof) ? "NA" : "data:image/" + AddressProofExt.Replace(".", "") + ";base64," + AddressProof;
                        addressForIndia.addressProofSrc = BakshishPatraInformation.address_proof_document_path;
                    }
                    else
                    {
                        addressForIndia.addressProofSrc = BakshishPatraInformation.address_proof_document_path;
                    }
                    //string SignatureExt = Path.GetExtension(BakshishPatraInformation.signed_file_path)!;
                    //string Signature = methodForFile.ConvertImageToBase64(BakshishPatraInformation.signed_file_path!);
                    //BakshishPatraInformation.signed_file_path = string.IsNullOrEmpty(Signature) ? "NA" : "data:image/" + SignatureExt.Replace(".", "") + ";base64," + Signature;
                    addressForIndia.signatureSrc = BakshishPatraInformation.signed_file_path!;
                    addressData.indiaAddress = addressForIndia;
                }
                else if (BakshishPatraInformation.address_type == "FOREIGN")
                {
                    InputDataModel.AddressForForeign addressForForeign = new InputDataModel.AddressForForeign();
                    addressForForeign.address = BakshishPatraInformation.address;
                    addressForForeign.mobile = BakshishPatraInformation.mobileno;
                    addressForForeign.email = BakshishPatraInformation.emailid;
                    addressForForeign.emailOTP = BakshishPatraInformation.emailidverified;
                    addressForForeign.signatureName = BakshishPatraInformation.signed_file_name;
                    //string SignatureExt = Path.GetExtension(BakshishPatraInformation.signed_file_path)!;
                    //string Signature = methodForFile.ConvertImageToBase64(BakshishPatraInformation.signed_file_path!);
                    //BakshishPatraInformation.signed_file_path = string.IsNullOrEmpty(Signature) ? "NA" : "data:image/" + SignatureExt.Replace(".", "") + ";base64," + Signature;
                    addressForForeign.signatureSrc = BakshishPatraInformation.signed_file_path;
                    addressData.foreignAddress = addressForForeign;
                }
                fetchData.address = addressData;
                return fetchData;
            }
            catch (Exception ex)
            {
                throw new HandleException(ex.Message.ToString());
            }
        }

        // मयत ,मृत्यू दाखला आणि वारस नोंद 
        public string SaveMayatDetails(MayatDetails mayatDetails)
        {
            using (var scope = new TransactionScope())
            {
                try
                {
                    TextInfo textInfo = new CultureInfo("en-US", false).TextInfo;
                    MethodForFileUpload methodForFile = new MethodForFileUpload();
                    string FolderPath = @"\\10.10.248.2\pde_propertycard\MUTATIONDOCS\" + mayatDetails.applicationid + @"\DEATHCERT";
                    // Assign Values to Model
                    if (string.IsNullOrEmpty(mayatDetails.ctsNo))
                    {
                        return "Plese select अर्जामधील न.भू.क्र. ";
                    }
                    if (string.IsNullOrEmpty(mayatDetails.userDetails!.firstName!))
                    {
                        return "Plese wait मयत धारकाचे नाव (मराठी मध्ये) is not fetched!";
                    }
                    if (string.IsNullOrEmpty(mayatDetails.userDetails!.firstNameEng!) ||
                        string.IsNullOrEmpty(mayatDetails.userDetails!.middleNameEng!) ||
                        string.IsNullOrEmpty(mayatDetails.userDetails!.lastNameEng!))
                    {
                        return "Plese enter मयत धारकाचे नाव (इंग्रजी मध्ये)";
                    }
                    if (methodForFile.ContainsSpecialCharactersInName(mayatDetails.userDetails!.firstNameEng!) ||
                        methodForFile.ContainsSpecialCharactersInName(mayatDetails.userDetails!.middleNameEng!) ||
                        methodForFile.ContainsSpecialCharactersInName(mayatDetails.userDetails!.lastNameEng!))
                    {
                        return "मयत धारकाचे नाव (इंग्रजी मध्ये) contains special characters / English Letters";
                    }
