        public FetchMayatDetailsData FetchMayatDetails(int mayatid)
        {
            try
            {
                MethodForFileUpload methodForFile = new MethodForFileUpload();
                MayatDTL mayatInfo = new MayatDTL();
                mayatInfo = _contextR.mayatDTL.Include(i => i.userMaster).Include(app => app.applicationDTL).Where(data => data.mayat_id.Equals(mayatid) && data.isDeleted == false).FirstOrDefault()!;

                FetchMayatDetailsData fetchData = new FetchMayatDetailsData();
                fetchData.mayat_id = mayatInfo.mayat_id;
                fetchData.userid = mayatInfo.userMaster!.userid;
                fetchData.applicationid = mayatInfo.applicationDTL!.applicationid;
                fetchData.fullNameInMarathi = commonFunctions.ReplaceNA(mayatInfo.fname_in_marathi!.Trim()) + " " + commonFunctions.ReplaceNA(mayatInfo.mname_in_marathi!.Trim()) + " " + commonFunctions.ReplaceNA(mayatInfo.lname_in_marathi!.Trim());
                fetchData.fullNameInEng = commonFunctions.ReplaceNA(mayatInfo.fname_in_eng!.Trim()) + " " + commonFunctions.ReplaceNA(mayatInfo.mname_in_eng!.Trim()) + " " + commonFunctions.ReplaceNA(mayatInfo.lname_in_eng!.Trim());
                fetchData.mobileNo = mayatInfo.mobileno;

                InputDataModel.UserDTLForMayat userDetails = new InputDataModel.UserDTLForMayat();
                userDetails.suffixcode = mayatInfo.prefixcode_marathi;
                userDetails.suffix = mayatInfo.prefix_in_marathi;
                userDetails.firstName = mayatInfo.fname_in_marathi == "NA" ? "" : mayatInfo.fname_in_marathi;
                userDetails.middleName = mayatInfo.mname_in_marathi == "NA" ? "" : mayatInfo.mname_in_marathi;
                userDetails.lastName = mayatInfo.lname_in_marathi == "NA" ? "" : mayatInfo.lname_in_marathi;
                userDetails.suffixCodeEng = mayatInfo.prefixcode_eng;
                userDetails.suffixEng = mayatInfo.prefix_in_eng;
                userDetails.firstNameEng = mayatInfo.fname_in_eng == "NA" ? "" : mayatInfo.fname_in_eng;
                userDetails.middleNameEng = mayatInfo.mname_in_eng == "NA" ? "" : mayatInfo.mname_in_eng;
                userDetails.lastNameEng = mayatInfo.lname_in_eng == "NA" ? "" : mayatInfo.lname_in_eng;
                userDetails.aliceName = mayatInfo.alias_name;
                //userDetails.holderType = mayatInfo.holder_type;
                //userDetails.dob = mayatInfo.dob;
                //userDetails.motherName = mayatInfo.mother_name_in_marathi;
                //userDetails.motherNameEng = mayatInfo.mother_name_in_eng;
                userDetails.nabhu = mayatInfo.city_servey_no;
                //userDetails.userName = mayatInfo.userName;
                userDetails.lrPropertyUID = mayatInfo.lr_property_id;
                userDetails.milkat = mayatInfo.milkat;
                userDetails.namud = mayatInfo.namud;
                userDetails.subPropNo = mayatInfo.sub_property_no;
                //userDetails.actualArea = mayatInfo.actual_area;
                //InputDataModel.Holdertype holdertype = new InputDataModel.Holdertype();
                //holdertype.account_type_code = mayatInfo.account_type_code;
                //holdertype.account_type_description = mayatInfo.account_type_description;
                //userDetails.holderType = holdertype;
                fetchData.userDetails = userDetails;

                areaForMutationForMayat area = new areaForMutationForMayat();
