                //Certificate Details
                /* InputDataModel.MrutucertificateDTL mrutudetails = new MrutucertificateDTL();
                 mrutudetails.mrutu_date = mayatInfo.mrutu_date;
                 mrutudetails.mrutucertificate_issued_ofc = mayatInfo.mrutucertificate_issued_ofc;
                 mrutudetails.ofc_name = mayatInfo.ofc_name;
                 mrutudetails.mrutucert_no = mayatInfo.mrutucert_no;
                 mrutudetails.mrutu_certificate_date = mayatInfo.mrutu_certificate_date;
                 mrutudetails.mruticertificatename = mayatInfo.mrutucert_certificate__name;
                 mrutudetails.behalf_off_name = mayatInfo.behalf_off_name;

                 string MrutuCertProofExt = Path.GetExtension(mayatInfo.mrutu_certificate_path)!;
                 string MrutuCertificate = methodForFile.ConvertImageToBase64(mayatInfo.mrutu_certificate_path!);
                 mayatInfo.mrutu_certificate_path = string.IsNullOrEmpty(MrutuCertificate) ? "NA" : "data:image/" + MrutuCertProofExt.Replace(".", "") + ";base64," + MrutuCertificate;*/

                //fetchData.mrutuDetails = mrutudetails;

                InputDataModel.AddressDTLForMayat addressData = new InputDataModel.AddressDTLForMayat();
                addressData.addressType = mayatInfo.address_type;
                if (mayatInfo.address_type == "INDIA")
                {
                    InputDataModel.IndiaAddressForKharediNond addressForIndia = new InputDataModel.IndiaAddressForKharediNond();
                    addressForIndia.state = mayatInfo.state;
                    addressForIndia.district = mayatInfo.district;
                    addressForIndia.city = mayatInfo.city;
                    addressForIndia.taluka = mayatInfo.taluka;
                    addressForIndia.plotNo = mayatInfo.flatno_plotno;
                    addressForIndia.building = mayatInfo.societyname;
                    addressForIndia.mainRoad = mayatInfo.mainstreet;
                    addressForIndia.impSymbol = mayatInfo.landmark;
                    addressForIndia.area = mayatInfo.locality;
                    addressForIndia.pincode = mayatInfo.pincode;
                    addressForIndia.postOfficeName = mayatInfo.post_office_name;
                    addressForIndia.addressProofName = mayatInfo.address_proof_document_name;
                    addressForIndia.mobile = mayatInfo.mobileno;
                    addressForIndia.mobileOTP = mayatInfo.mobilenoverified;
                    addressForIndia.signatureName = mayatInfo.signed_file_name!;
                    /*if (addressForIndia.addressProofName != "NA")
                        addressForIndia.addressProofSrc = mayatInfo.address_proof_src == null ? "" : Convert.ToBase64String(mayatInfo.address_proof_src);
