                    //mayatInfo.signed_file_path = string.IsNullOrEmpty(Signature) ? "NA" : "data:image/" + SignatureExt.Replace(".", "") + ";base64," + Signature;
                    addressForIndia.signatureSrc = mayatInfo.signed_file_path!;
                    addressData.indiaAddress = addressForIndia;
                }
                else if (mayatInfo.address_type == "FOREIGN")
                {
                    InputDataModel.AddressForForeign addressForForeign = new InputDataModel.AddressForForeign();
                    addressForForeign.address = mayatInfo.address;
                    addressForForeign.mobile = mayatInfo.mobileno;
                    addressForForeign.email = mayatInfo.emailid;
                    addressForForeign.emailOTP = mayatInfo.emailidverified;
                    addressForForeign.signatureName = mayatInfo.signed_file_name;
                    /*  if (addressForForeign.signatureName != "NA")
