                    //mayatInfo.signed_file_path = string.IsNullOrEmpty(Signature) ? "NA" : "data:image/" + SignatureExt.Replace(".", "") + ";base64," + Signature;
                    addressForForeign.signatureSrc = mayatInfo.signed_file_path;
                    addressData.foreignAddress = addressForForeign;
                }
                fetchData.address = addressData;
                return fetchData;
            }
            catch (Exception ex)
            {
                throw new HandleException(ex.Message.ToString());
            }
        }

        public string SaveMrutuDakhlaDetails(MrutuDakhalaDetails mayatDetails)
        {
            using (var scope = new TransactionScope())
