        public string DeleteMayat(DeleteMayat deleteMutation)
        {
            MethodForFileUpload methodForFile = new MethodForFileUpload();
            string FolderPath = @"\\10.10.248.2\pde_propertycard\MUTATIONDOCS\" + deleteMutation.applicationid + @"\DEATHCERT";
            using (var scope = new TransactionScope())
            {
                try
                {
                    var entity = _context.mayatDTL.FirstOrDefault(s => s.mayat_id == deleteMutation.MayatId!)!;
                    if (entity != null)
                    {
                        entity.isDeleted = true;
                        entity.deleteddate = DateOnly.FromDateTime(DateTime.Now);
                        _context.mayatDTL.Attach(entity);
                        _context.SaveChanges();
                        var applicationDTLdata = _context.applicationDTL.Where(data => data.applicationid!.Equals(deleteMutation.applicationid)).FirstOrDefault();
                        if (applicationDTLdata != null)
                        {
                            string mutationtakerids = applicationDTLdata.mayatIDs!;
                            string[] mutationids = mutationtakerids.Split(',');
                            var updatedIds = mutationids.Where(id => id != deleteMutation.MayatId.ToString());

                            // Join the remaining IDs back into a string
                            string result = string.Join(",", updatedIds);
                            applicationDTLdata.mayatIDs = result;
                            _context.Entry(applicationDTLdata).CurrentValues.SetValues(applicationDTLdata);
                            _context.SaveChanges();
                        }
                        var entityForDoc = _context.uploadedDocumentsDTLs.Include(app => app.applicationDTL).Where(data => data.applicationDTL!.applicationid!.Equals(deleteMutation.applicationid)
                      && data.isDeleted == false && data.document_path == entity.mrutyu_certificate_path).FirstOrDefault();
                        if (!string.IsNullOrEmpty(entity.mrutyu_certificate_path) && entityForDoc != null)
                        {
                            methodForFile.DeleteFile(entity.mrutyu_certificate_path!);
                            _context.uploadedDocumentsDTLs.Remove(entityForDoc!);
                            _context.SaveChanges();
                        }
                        FolderPath = FolderPath + @"\" + deleteMutation.MayatId;

                        if (Directory.Exists(FolderPath))
                        {
                            if (Directory.GetFiles(FolderPath).Length > 0)
                            {
                                string[] fetchfilePath = Directory.GetFiles(FolderPath);

                                foreach (string file in fetchfilePath)
                                {
                                    methodForFile.DeleteFile(file);
                                }
                            }
                            if (Directory.GetFiles(FolderPath).Length == 0 && Directory.GetDirectories(FolderPath).Length == 0)
                            {
                                Directory.Delete(FolderPath);
                            }
                        }
                        FolderPath = @"\\10.10.248.2\pde_propertycard\MUTATIONDOCS\" + deleteMutation.applicationid + @"\DEATHCERT";
                        if (Directory.Exists(FolderPath))
                        {
                            if (Directory.GetFiles(FolderPath).Length == 0 && Directory.GetDirectories(FolderPath).Length == 0)
                            {
                                Directory.Delete(FolderPath);
                            }
                        }
                        scope.Complete();
                        return "Success";
                    }
                    else { return "False"; }
                }
                catch (Exception ex)
                {
                    throw new HandleException(ex.Message.ToString());
                }
            }
        }


