        public string SaveVarasDetails(VarasDetails varasDetails)
        {
            TextInfo textInfo = new CultureInfo("en-US", false).TextInfo;
            MethodForFileUpload methodForFile = new MethodForFileUpload();
            MutationGiverTakerDTL dbTable = new MutationGiverTakerDTL();
            using (var scope = new TransactionScope())
            {
                try
                {
                    if (string.IsNullOrEmpty(varasDetails.IsMHProperty!.userDetails!.firstName!))
                    {
                        return "Please enter वारसाचे नाव (मराठी मध्ये)";
                    }
                    if (string.IsNullOrEmpty(varasDetails.IsMHProperty!.userDetails!.firstNameEng!))
                    {
                        return "Please enter वारसाचे नाव  (इंग्रजी मध्ये)";
                    }

                    if (string.IsNullOrEmpty(varasDetails.dharak!.holderType!.account_type_description!))
                    {
                        return "Please select धारक प्रकार";
                    }
                    if (string.IsNullOrEmpty(varasDetails.dharak!.deadRelation!.relation_name!))
                    {
                        return "Please select मयत धारकाशी नाते";
                    }
                    if (string.IsNullOrEmpty(varasDetails.dharak!.gender!.gender_description!))
                    {
                        return "Please select लिंग";
                    }
                    if (string.IsNullOrEmpty(varasDetails.dharak!.dob))
                    {
                        return "Please select जन्म दिनांक";
                    }
                    string FolderPath = @"\\10.10.248.2\pde_propertycard\MUTATIONDOCS\" + varasDetails.applicationid + @"\VARAS";
                    // Assign Values to Model
                    KharediNondModel kharediNondModel = new KharediNondModel();
                    UserMaster userMaster = _context.userMasters.FirstOrDefault(s => s.userid == varasDetails.userid!)!;
                    kharediNondModel.userMaster = userMaster;

                    ApplicationDTL applicationDTL = _context.applicationDTL.FirstOrDefault(s => s.applicationid == varasDetails.applicationid!)!;
                    kharediNondModel.applicationDTL = applicationDTL;

                    /*MayatDTL mayatDTL = _context.mayatDTL.FirstOrDefault(s => s.mayat_id == varasDetails.mayat_id!)!;
                    kharediNondModel.mayatDTL = mayatDTL;*/

                    PropertyTypeMaster proptype = _context.propertyTypes.FirstOrDefault(s => s.propertytypeid == Convert.ToInt32(varasDetails.IsMHProperty!.propType!))!;
                    kharediNondModel.propType = proptype;

                    kharediNondModel.address_type = varasDetails.address!.addressType!.Trim().ToUpper();
                    if (kharediNondModel.address_type == "INDIA")
                    {
                        if (string.IsNullOrEmpty(varasDetails.address!.indiaAddress!.plotNo))
                        {
                            return "Please enter सदनिका / घर /प्लॉट नं.";
                        }

                        if (string.IsNullOrEmpty(varasDetails.address!.indiaAddress!.impSymbol))
                        {
                            return "Please enter महत्त्वाची खूण";
                        }
                        if (string.IsNullOrEmpty(varasDetails.address!.indiaAddress!.pincode))
                        {
                            return "Please enter पिन कोड";
                        }
                        if (!string.IsNullOrEmpty(varasDetails.address!.indiaAddress!.pincode) && methodForFile.CheckPinCode(varasDetails.address!.indiaAddress!.pincode))
                        {
                            if (string.IsNullOrEmpty(varasDetails.address!.indiaAddress!.postOfficeName))
                            {
                                return "Please select Post Office Name / Enter correct Pin Code.";
                            }
                            return "पिन कोड field contains special characters";
                        }
                        if (string.IsNullOrEmpty(varasDetails.address!.indiaAddress!.mobile))
                        {
                            return "Please enter मोबाईल";
                        }
                        if (string.IsNullOrEmpty(varasDetails.address!.indiaAddress!.mobileOTP) && varasDetails.address!.indiaAddress!.mobileOTP.ToLower() == "no")
                        {
                            return "Please varify मोबाईल नंबर";
                        }

                        if (methodForFile.CheckIndianAddress(varasDetails.address!.indiaAddress!.plotNo))
                        {
                            return "सदनिका / घर /प्लॉट नं. field contains special characters";
                        }
                        if (!string.IsNullOrEmpty(varasDetails.address!.indiaAddress!.building!) && methodForFile.CheckIndianAddress(varasDetails.address!.indiaAddress!.building!))
                        {
                            return "इमारत (बिल्डिंग)/सोसायटी क्रमांक किंवा नाव field contains special characters";
                        }
                        if (!string.IsNullOrEmpty(varasDetails.address!.indiaAddress!.mainRoad!) && methodForFile.CheckIndianAddress(varasDetails.address!.indiaAddress!.mainRoad!))
                        {
                            return "मुख्य रस्ता field contains special characters";
                        }
                        if (methodForFile.CheckIndianAddress(varasDetails.address!.indiaAddress!.impSymbol!))
                        {
                            return "महत्त्वाची खूण field contains special characters";
                        }
                        if (!string.IsNullOrEmpty(varasDetails.address!.indiaAddress!.area!) && methodForFile.CheckIndianAddress(varasDetails.address!.indiaAddress!.area!))
                        {
                            return "महत्त्वाची खूण field contains special characters";
                        }
                        if (!string.IsNullOrEmpty(varasDetails.address!.indiaAddress!.mobile!) && methodForFile.CheckMobNo(varasDetails.address!.indiaAddress!.mobile!))
                        {
                            return "मोबाईल field contains special characters";
                        }
                        //if (methodForFile.CheckPinCode(varasDetails.address!.indiaAddress!.pincode!))
                        //{
                        //    return "पिन कोड field contains special characters";
                        //}
                        kharediNondModel.mobileno = varasDetails.address.indiaAddress!.mobile;
                        kharediNondModel.mobilenoverified = varasDetails.address.indiaAddress.mobileOTP;
                        kharediNondModel.emailid = "NA";
                        kharediNondModel.emailidverified = "NA";

                        kharediNondModel.address = "NA";
                        kharediNondModel.state = varasDetails.address.indiaAddress.state;
                        kharediNondModel.district = varasDetails.address.indiaAddress.district;
                        kharediNondModel.taluka = varasDetails.address.indiaAddress.taluka;
                        kharediNondModel.city = varasDetails.address.indiaAddress.city;
                        kharediNondModel.plotno = varasDetails.address.indiaAddress.plotNo;
                        kharediNondModel.building = varasDetails.address.indiaAddress.building;
                        kharediNondModel.mainroad = varasDetails.address.indiaAddress.mainRoad;
                        kharediNondModel.impSymbol = varasDetails.address.indiaAddress.impSymbol;
                        kharediNondModel.area = varasDetails.address.indiaAddress.area;
                        kharediNondModel.pincode = varasDetails.address.indiaAddress.pincode;
                        kharediNondModel.post_office_name = varasDetails.address.indiaAddress.postOfficeName;
                    }
                    else if (kharediNondModel.address_type == "FOREIGN")
                    {
                        if (string.IsNullOrEmpty(varasDetails.address.foreignAddress!.address) || string.IsNullOrEmpty(varasDetails.address.foreignAddress!.email))
                        {
                            return "पत्ता and ई मेल field is mandatory";
                        }
                        if (methodForFile.CheckForeignAddress(varasDetails.address.foreignAddress!.address))
                        {
                            return "पत्ता field contains special characters";
                        }
                        if (methodForFile.CheckEmail(varasDetails.address.foreignAddress!.email))
                        {
                            return "ई मेल field contains special characters";
                        }
                        kharediNondModel.address = varasDetails.address.foreignAddress!.address;
