                        kharediNondModel.building = "NA";
                        kharediNondModel.mainroad = "NA";
                        kharediNondModel.impSymbol = "NA";
                        kharediNondModel.area = "NA";
                        kharediNondModel.pincode = "NA";
                        kharediNondModel.post_office_name = "NA";
                    }

                    kharediNondModel.usertype_code = varasDetails.usertype_code;
                    kharediNondModel.usertype = varasDetails.usertype;

                    //isMHproperty
                    kharediNondModel.hasProperty = varasDetails.IsMHProperty!.hasProperty;
                    // kharediNondModel.propType = bakshishpatraDataForTaker.isMHProperty.propType;
                    if (kharediNondModel.hasProperty!.Trim().ToUpper() == "YES")
                    {
                        if (kharediNondModel.propType.propertytypeid == 1 && string.IsNullOrEmpty(varasDetails.IsMHProperty!.userDetails!.khataNo))
                        {
                            return "When Property Type Is 7/12 Then Khate No Should Not Be Empty";
                        }
                        if (kharediNondModel.propType.propertytypeid == 2 && string.IsNullOrEmpty(varasDetails.IsMHProperty!.userDetails!.naBhu))
                        {
                            return "When Property Type Is Property Card Then City Servey No Should Not Be Empty";
                        }
                        if (kharediNondModel.propType.propertytypeid == 3 && string.IsNullOrEmpty(varasDetails.IsMHProperty!.userDetails!.ulpin))
                        {
                            return "When Property Type Is ULPIN Then ULPIN Should Not Be Empty";
                        }
                        kharediNondModel.khatano = string.IsNullOrEmpty(varasDetails.IsMHProperty!.userDetails!.khataNo) ? "NA" : varasDetails.IsMHProperty.userDetails.khataNo;
                        kharediNondModel.city_servey_no = string.IsNullOrEmpty(varasDetails.IsMHProperty.userDetails.naBhu) ? "NA" : varasDetails.IsMHProperty.userDetails.naBhu;
                        kharediNondModel.ulpin = string.IsNullOrEmpty(varasDetails.IsMHProperty.userDetails.ulpin) ? "NA" : varasDetails.IsMHProperty.userDetails.ulpin;
                        if (kharediNondModel.propType.propertytypeid == 1)
                        {
                            kharediNondModel.city_servey_no = "NA";
                            kharediNondModel.ulpin = "NA";
