                        {
                            kharediNondModel.khatano = "NA";
                            kharediNondModel.ulpin = "NA";
                        }
                        else if (kharediNondModel.propType.propertytypeid == 3)
                        {
                            kharediNondModel.khatano = "NA";
                            kharediNondModel.city_servey_no = "NA";
                        }
