                        kharediNondModel.district_code = varasDetails.IsMHProperty.userDetails.district!.district_code;
                        kharediNondModel.district_name_in_marathi = varasDetails.IsMHProperty.userDetails.district!.district_name!;
                        kharediNondModel.district_name_in_eng = varasDetails.IsMHProperty.userDetails.district!.district_english_name!;
