        public string SaveHakkaSodGiver(HakkasodDataForGiver hakkasodData)
        {
            MethodForFileUpload methodForFile = new MethodForFileUpload();
            MutationGiverTakerDTL dbTable = new MutationGiverTakerDTL();
            MutationGiverTakerDTL fetchData = new MutationGiverTakerDTL();
            string FolderPath = @"\\10.10.248.2\pde_propertycard\MUTATIONDOCS\" + hakkasodData.applicationid + @"\GIVER";
            using (var scope = new TransactionScope())
            {
                try
                {
                    TextInfo textInfo = new CultureInfo("en-US", false).TextInfo;
                    // Assign Values to Model
                    HakkasodModel modelData = new HakkasodModel();

                    if (hakkasodData.userDetails != null && !string.IsNullOrEmpty(hakkasodData.userDetails.firstName))
                    {

                        if (string.IsNullOrEmpty(hakkasodData.userDetails!.nabhu!))
                        {
                            return "Please select अर्जामधील न.भू.क्र.";
                        }
                        if (string.IsNullOrEmpty(hakkasodData.userDetails!.firstNameEng!))
                        {
                            return "Please select हक्कसोड देणाराचे नाव (इंग्रजी मध्ये)";
                        }
                        if (string.IsNullOrEmpty(hakkasodData.areaForMutation!.actualArea!))
                        {
                            return "Please wait, मिळकत पत्रिके प्रमाणे क्षेत्र (चौ.मी.) is not fetched.";
                        }

                        //if (methodForFile.ContainsSpecialCharactersInMarathiName(hakkasodData.userDetails!.firstName!))
                        //{
                        //    return "देणाऱ्याचे नाव (मराठी मध्ये) Field contains English Letters / special characters / Numbers!";
                        //}
                        if (methodForFile.ContainsSpecialCharactersInName(hakkasodData.userDetails!.firstNameEng!) &&
                            methodForFile.ContainsSpecialCharactersInName(hakkasodData.userDetails!.middleNameEng!) &&
                            methodForFile.ContainsSpecialCharactersInName(hakkasodData.userDetails!.lastNameEng!))
                        {
                            return "देणाऱ्याचे नाव (इंग्रजी मध्ये) Field contains special characters!";
                        }
                        if (methodForFile.ContainsSpecialCharactersInMarathiName(hakkasodData.userDetails!.aliceName!))
                        {
                            return "देणाऱ्याचे उर्फ नाव (मराठी मध्ये) Field contains English Letter / special characters!";
                        }
                        if (methodForFile.ContainsSpecialCharactersInName(hakkasodData.userDetails!.motherNameEng!))
                        {
                            return "आईचे नाव (इंग्रजी मध्ये) Field contains special characters!";
                        }
                        if (methodForFile.ContainsSpecialCharactersInMarathiName(hakkasodData.userDetails!.motherName!))
                        {
                            return "आईचे नाव (मराठी मध्ये) Field contains English Letters / special characters / Numbers!";
                        }

                        if (!string.IsNullOrEmpty(hakkasodData.areaForMutation!.availableArea!) && methodForFile.CheckKArea(hakkasodData.areaForMutation!.availableArea!))
                        {
                            return "मिळकत पत्रिके प्रमाणे क्षेत्र (चौ.मी.) field contains special character / please enter 10 digit मिळकत पत्रिके प्रमाणे क्षेत्र (चौ.मी.)";
                        }
                        if (!string.IsNullOrEmpty(hakkasodData.areaForMutation!.mutationArea!) && methodForFile.CheckKArea(hakkasodData.areaForMutation!.mutationArea!))
                        {
                            return "हक्कसोड देणाऱ्याच्या नावे क्षेत्र (चौ.मी.) field contains special character / please enter 10 digit हक्कसोड देणाऱ्याच्या नावे क्षेत्र (चौ.मी.)";
                        }

                        //if (methodForFile.CheckKArea(hakkasodData.areaForMutation!.actualArea!))
                        //{
                        //    return "हक्कसोड क्षेत्र (चौ.मी.) field contains special character / please enter 10 digit हक्कसोड देणाऱ्याच्या नावे क्षेत्र (चौ.मी.)";
                        //}
