                            modelData.owner_village_code = hakkasodData.village_code;
                            modelData.ctsNo = hakkasodData.ctsNo;
                            modelData.mutationSroNo = hakkasodData.mutationSroNo;
                            modelData.ownerNo = hakkasodData.ownerNo;

                            modelData.address_type = hakkasodData.address!.addressType!.Trim().ToUpper();
                            if (modelData.address_type == "INDIA")
                            {
                                if (string.IsNullOrEmpty(hakkasodData.address!.indiaAddress!.plotNo))
                                {
                                    return "Please enter सदनिका / घर /प्लॉट नं.";
                                }
                                if (string.IsNullOrEmpty(hakkasodData.address!.indiaAddress!.impSymbol))
                                {
                                    return "Please enter महत्त्वाची खूण";
                                }
                                if (string.IsNullOrEmpty(hakkasodData.address!.indiaAddress!.pincode))
                                {
                                    return "Please enter पिन कोड";
                                }
                                if (!string.IsNullOrEmpty(hakkasodData.address!.indiaAddress!.pincode) && methodForFile.CheckPinCode(hakkasodData.address!.indiaAddress!.pincode))
                                {
                                    if (string.IsNullOrEmpty(hakkasodData.address!.indiaAddress!.postOfficeName))
                                    {
                                        return "Please select Post Office Name / Enter correct Pin Code.";
                                    }
                                    return "पिन कोड field contains special characters";
                                }

                                if (methodForFile.CheckIndianAddress(hakkasodData.address!.indiaAddress!.plotNo))
                                {
                                    return "सदनिका / घर /प्लॉट नं. field contains special characters";
                                }
                                if (!string.IsNullOrEmpty(hakkasodData.address!.indiaAddress!.building!) && methodForFile.CheckIndianAddress(hakkasodData.address!.indiaAddress!.building!))
                                {
                                    return "इमारत (बिल्डिंग)/सोसायटी क्रमांक किंवा नाव field contains special characters";
                                }
                                if (!string.IsNullOrEmpty(hakkasodData.address!.indiaAddress!.mainRoad!) && methodForFile.CheckIndianAddress(hakkasodData.address!.indiaAddress!.mainRoad!))
                                {
                                    return "मुख्य रस्ता field contains special characters";
                                }
                                if (methodForFile.CheckIndianAddress(hakkasodData.address!.indiaAddress!.impSymbol!))
                                {
                                    return "महत्त्वाची खूण field contains special characters";
                                }
                                if (!string.IsNullOrEmpty(hakkasodData.address!.indiaAddress!.area!) && methodForFile.CheckIndianAddress(hakkasodData.address!.indiaAddress!.area!))
                                {
                                    return "महत्त्वाची खूण field contains special characters";
                                }
                                if (!string.IsNullOrEmpty(hakkasodData.address!.indiaAddress!.mobile!) && methodForFile.CheckMobNo(hakkasodData.address!.indiaAddress!.mobile!))
                                {
                                    return "मोबाईल field contains special characters";
                                }
                                //if (methodForFile.CheckPinCode(hakkasodData.address!.indiaAddress!.pincode!))
                                //{
                                //    return "पिन कोड field contains special characters";
