                    areaForMutation.availableArea = mutationGiverTakerDTL.available_area;
                    fetchData.areaForMutation = areaForMutation;
                }
                else
                {
                    fetchData = null!;
                }
                return fetchData;
            }
            catch (Exception ex)
            {
                throw new HandleException(ex.Message.ToString());
            }
        }

