                                    var UpdateAddressFilePath = _context.mutationDTL.Where(w => w.mutation_givertaker_id == kharediNondID).FirstOrDefault();
                                    if (UpdateAddressFilePath != null)
                                    {
                                        entity.address_proof_document_name = kharediNondModel.address_proof_name;
                                        entity.address_proof_document_path = kharediNondModel.address_proof_src;
                                        _context.Entry(entity).CurrentValues.SetValues(entity);
                                        _context.SaveChanges();
                                    }
                                }
                            }
