        public FetchHakkaSodTaker FetchHakkaSodInfoForTaker(int mutationdtlid)
        {
            try
            {
                MethodForFileUpload methodForFile = new MethodForFileUpload();
                MutationGiverTakerDTL mutation = new MutationGiverTakerDTL();
                mutation = _contextR.mutationDTL.Include(i => i.userMaster).Include(app => app.applicationDTL).Include(prop => prop.prop_type).Where(data => data.mutation_givertaker_id.Equals(mutationdtlid) && data.isDeleted == false).FirstOrDefault()!;

                FetchHakkaSodTaker fetchData = new FetchHakkaSodTaker();
                fetchData.mutation_dtl_id = mutation.mutation_givertaker_id;
                fetchData.userid = mutation.userMaster!.userid;
                fetchData.applicationid = mutation.applicationDTL!.applicationid;
                fetchData.mutationSroNo = mutation.mutation_srno;
                fetchData.ownerNo = mutation.owner_number;
                fetchData.ctsNo = mutation.cts_number;

                fetchData.mobileNo = mutation.mobileno;

                //fetchData.fullNameInMarathi = mutation.fname_in_marathi!.Trim() + " " + mutation.mname_in_marathi!.Trim() + " " + mutation.lname_in_marathi!.Trim();
                //fetchData.fullNameInEng = mutation.fname_in_eng!.Trim() + " " + mutation.mname_in_eng!.Trim() + " " + mutation.lname_in_eng!.Trim();
                fetchData.fullNameInMarathi = commonFunctions.ReplaceNA(mutation.fname_in_marathi!.Trim()) + " " + commonFunctions.ReplaceNA(mutation.mname_in_marathi!.Trim()) + " " + commonFunctions.ReplaceNA(mutation.lname_in_marathi!.Trim());
                fetchData.fullNameInEng = commonFunctions.ReplaceNA(mutation.fname_in_eng!.Trim()) + " " + commonFunctions.ReplaceNA(mutation.mname_in_eng!.Trim()) + " " + commonFunctions.ReplaceNA(mutation.lname_in_eng!.Trim());

                InputDataModel.userDetailsHakkaSod takeruserDetails = new userDetailsHakkaSod();
                takeruserDetails!.suffixcode = mutation.prefixcode_marathi;
                takeruserDetails!.suffix = mutation.prefix_in_marathi;
                takeruserDetails.firstName = mutation.fname_in_marathi;
                takeruserDetails.middleName = mutation.mname_in_marathi;
                takeruserDetails.lastName = mutation.lname_in_marathi;
                takeruserDetails.suffixCodeEng = mutation.prefixcode_eng;
                takeruserDetails.suffixEng = mutation.prefix_in_eng;
                takeruserDetails.firstNameEng = mutation.fname_in_eng;
                takeruserDetails.middleNameEng = mutation.mname_in_eng;
                takeruserDetails.lastNameEng = mutation.lname_in_eng;
                takeruserDetails.aliceName = mutation.alias_name!;
                takeruserDetails.dob = mutation.dob!;
                takeruserDetails.motherName = mutation.mother_name_in_marathi;
                takeruserDetails.motherNameEng = mutation.mother_name_in_eng;
                takeruserDetails.mutationArea = mutation.mutation_area;
                takeruserDetails.benefitAmount = mutation.benefit_amt;
                takeruserDetails.userName = mutation.userName;
                takeruserDetails.nabhu = mutation.city_servey_no;
                takeruserDetails.lrPropertyUID = mutation.lr_property_id;
                takeruserDetails.milkat = mutation.milkat;
                takeruserDetails.namud = mutation.namud;
                takeruserDetails.subPropNo = mutation.sub_property_no;

                InputDataModel.Holdertype holdertype = new InputDataModel.Holdertype();
                holdertype.owner_status_code = mutation.owner_status_code;
                holdertype.owner_status_description = mutation.owner_status_description;
                takeruserDetails.holderType = holdertype;

                fetchData.userDetails = takeruserDetails;


                //Address Details
                InputDataModel.AddressDTLForKharediNond addressData = new InputDataModel.AddressDTLForKharediNond();
                addressData.addressType = mutation.address_type;
                if (mutation.address_type == "INDIA")
                {
                    InputDataModel.IndiaAddressForKharediNond addressForIndia = new InputDataModel.IndiaAddressForKharediNond();
                    addressForIndia.state = mutation.state;
                    addressForIndia.district = mutation.district;
                    addressForIndia.city = mutation.city;
                    addressForIndia.taluka = mutation.taluka;
                    addressForIndia.plotNo = mutation.flatno_plotno;
                    addressForIndia.building = mutation.societyname;
                    addressForIndia.mainRoad = mutation.mainstreet;
                    addressForIndia.impSymbol = mutation.landmark;
                    addressForIndia.area = mutation.locality;
                    addressForIndia.pincode = mutation.pincode;
                    addressForIndia.postOfficeName = mutation.post_office_name;
                    addressForIndia.addressProofName = mutation.address_proof_document_name;
                    addressForIndia.mobile = mutation.mobileno;
                    addressForIndia.mobileOTP = mutation.mobilenoverified;
                    addressForIndia.signatureName = mutation.signed_file_name!;
                    /*if (addressForIndia.addressProofName != "NA")
                        addressForIndia.addressProofSrc = KharedinondInformation.address_proof_src == null ? "" : Convert.ToBase64String(KharedinondInformation.address_proof_src);
                    else addressForIndia.addressProofSrc = "";
                    if (addressForIndia.signatureName != "NA")
                        addressForIndia.signatureSrc = KharedinondInformation.signature_src == null ? "" : Convert.ToBase64String(KharedinondInformation.signature_src);
                    else addressForIndia.signatureSrc = "";*/

                    if (mutation.address_proof_document_path != "NA")
                    {
                        string AddressProofExt = Path.GetExtension(mutation.address_proof_document_path)!;
                        string AddressProof = methodForFile.ConvertImageToBase64(mutation.address_proof_document_path!);
                        mutation.address_proof_document_path = string.IsNullOrEmpty(AddressProof) ? "NA" : "data:image/" + AddressProofExt.Replace(".", "") + ";base64," + AddressProof;
                        addressForIndia.addressProofSrc = mutation.address_proof_document_path;
                    }
                    else
                    {
                        addressForIndia.addressProofSrc = mutation.address_proof_document_path;
                    }
                    //string SignatureExt = Path.GetExtension(mutation.signed_file_path)!;
                    //string Signature = methodForFile.ConvertImageToBase64(mutation.signed_file_path!);
                    //mutation.signed_file_path = string.IsNullOrEmpty(Signature) ? "NA" : "data:image/" + SignatureExt.Replace(".", "") + ";base64," + Signature;
                    addressForIndia.signatureSrc = mutation.signed_file_path!;
                    addressData.indiaAddress = addressForIndia;
                }
                else if (mutation.address_type == "FOREIGN")
                {
                    InputDataModel.AddressForForeign addressForForeign = new InputDataModel.AddressForForeign();
                    addressForForeign.address = mutation.address;
                    addressForForeign.mobile = mutation.mobileno;
                    addressForForeign.email = mutation.emailid;
                    addressForForeign.emailOTP = mutation.emailidverified;
                    addressForForeign.signatureName = mutation.signed_file_name;
                    /*  if (addressForForeign.signatureName != "NA")
                          addressForForeign.signatureSrc = KharedinondInformation.signature_src == null ? "" : Convert.ToBase64String(KharedinondInformation.signature_src);
                      else addressForForeign.signatureSrc = "";*/

                    //string SignatureExt = Path.GetExtension(mutation.signed_file_path)!;
                    //string Signature = methodForFile.ConvertImageToBase64(mutation.signed_file_path!);
                    //mutation.signed_file_path = string.IsNullOrEmpty(Signature) ? "NA" : "data:image/" + SignatureExt.Replace(".", "") + ";base64," + Signature;
                    addressForForeign.signatureSrc = mutation.signed_file_path;

                    addressData.foreignAddress = addressForForeign;
                }
                fetchData.address = addressData;
                return fetchData;
            }
            catch (Exception ex)
            {
                throw new HandleException(ex.Message.ToString());
            }
        }

