                            string[] mutationids = mutationtakerids.Split(',');
                            var updatedIds = mutationids.Where(id => id != deleteMutation.MutationId.ToString());

                            methodForFileUpload.PermanatlyDeleteFile(entity.address_proof_document_path!);

                            // Join the remaining IDs back into a string
                            string result = string.Join(",", updatedIds);
                            applicationDTLdata.mutationtakerIDs = result;
                            _context.Entry(applicationDTLdata).CurrentValues.SetValues(applicationDTLdata);
                            _context.SaveChanges();
                        }
                        scope.Complete();
                        //gauri w
                        methodForFileUpload.PermanatlyDeleteFile(entity.address_proof_document_path!);
                        var path = @"\\10.10.248.2\pde_propertycard\MUTATIONDOCS\" + deleteMutation.applicationid + @"\TAKER\" + deleteMutation.MutationId;
                        bool isDeleted = methodForFileUpload.PermanatlyDeleteFile(path);
                        return "Success";
                    }
                    else { return "False"; }
                }
                catch (Exception ex)
                {
                    throw new HandleException(ex.Message.ToString());
                }
            }
        }
