        public FetchApplicationDTLs GetApplicationDtls(ApplicationDTL application1)
        {
            FetchApplicationDTLs application = new FetchApplicationDTLs();
            application.applicationid = application1.applicationid;
            //application.userid = application1.userMaster!.userid == null?"":application1.userMaster!.userid;
            application.applicantIDs = application1.applicantIDs;
            application.applicationdate = application1.createddatetime.ToString("dd/MM/yyyy");
            application.applicationType = application1.applicationTypeMaster!.application_type_name_in_marathi;
            application.applicationTypeEng = application1.applicationTypeMaster!.application_type_name_in_eng;
            application.MutationTypeCode = application1.mutation_type_code;
            application.MutationTypeName = application1.mutation_type_name;
            application.DistrictCode = application1.district_code;
            application.DistrictName = application1.district_name_in_marathi;
            application.DistrictNameEng = application1.district_name_in_english;
            application.OfficeCode = application1.office_code;
            application.OfficeName = application1.office_name;
            application.do_you_have_power_of_attorney = application1.do_you_have_power_of_attorney;
            application.Is_the_claim_pending_before_the_court = application1.Is_the_claim_pending_before_the_court;
            application.does_the_original_charter_info_apply = application1.does_the_original_charter_info_apply;
            return application;
        }

        public List<dynamic> mutationgiverData(ApplicationDTL applicationDTL)
        {
            List<dynamic> mutationgiver = new List<dynamic>();
            //Kharedi Nond Giver
            if (applicationDTL.mutation_type_code == "03")
            {
                mutationgiver = new List<dynamic>();
                if (!string.IsNullOrEmpty(applicationDTL.mutationgiverIDs))
                {
                    string[] kharediNondIDs = applicationDTL.mutationgiverIDs.Split(",");

                    if (kharediNondIDs.Length > 0)
                    {
                        for (int i = 0; i < kharediNondIDs.Length; i++)
                        {
                            FetchKharediNondDataForGiver fetchKharediNondGiverInformationData = new FetchKharediNondDataForGiver();
                            fetchKharediNondGiverInformationData = FetchKhrediNondInformationDataForGiver(Convert.ToInt32(kharediNondIDs[i]));
                            if (fetchKharediNondGiverInformationData != null)
                            {
                                mutationgiver.Add(fetchKharediNondGiverInformationData);
                            }
                        }

                    }
                }
            }
            //Bakshish Patra
            else if (applicationDTL.mutation_type_code == "04")
            {
                mutationgiver = new List<dynamic>();
                if (!string.IsNullOrEmpty(applicationDTL.mutationgiverIDs))
                {
                    string[] mutationgiverIDs = applicationDTL.mutationgiverIDs.Split(",");
                    if (mutationgiverIDs.Length > 0)
                    {
                        for (int i = 0; i < mutationgiverIDs.Length; i++)
                        {
                            FetchBakshishPatraDataForGiver fetchKharediNondGiverInformationData = new FetchBakshishPatraDataForGiver();
                            fetchKharediNondGiverInformationData = FetchBakshishPatraInformationDataForGiver(Convert.ToInt32(mutationgiverIDs[i]));
                            if (fetchKharediNondGiverInformationData != null)
                            {
                                mutationgiver.Add(fetchKharediNondGiverInformationData);
                            }
                        }

                    }
                }
            }
            //Mrutyu Nond
            // Gauri W
            else if (applicationDTL.mutation_type_code == "05")
            {
                if (applicationDTL != null && !string.IsNullOrEmpty(applicationDTL.mutationgiverIDs) && !string.IsNullOrEmpty(applicationDTL.mayatIDs))
                {
                    string[] mutationgiverIDs = applicationDTL.mutationgiverIDs.Split(",");
                    string[] mayatIds = applicationDTL.mayatIDs.Split(",");

                    if (mutationgiverIDs.Length > 0 && mayatIds.Length > 0)
                    {
                        for (int i = 0; i < mutationgiverIDs.Length; i++)
                        {
                            for (int j = 0; j < mayatIds.Length; j++)
                            {
                                FetchMrutyuPatraForGiverData fetchData = new FetchMrutyuPatraForGiverData();
                                fetchData = FetchMrutyuPatraInfoForGiver(Convert.ToInt32(mutationgiverIDs[i]), Convert.ToInt32(mayatIds[j]));
                                if (fetchData != null)
                                {
                                    mutationgiver.Add(fetchData);
                                }
                            }

                        }
                    }
                }
            }
            //Gahankhat Nond
            else if (applicationDTL.mutation_type_code == "06")
            {
                if (!string.IsNullOrEmpty(applicationDTL.mutationgiverIDs))
                {
                    string[] mutationgiverIDs = applicationDTL!.mutationgiverIDs!.Split(",");
                    for (int i = 0; i < mutationgiverIDs.Length; i++)
                    {
                        FetchGahankhatDataForGiver fetchData = new FetchGahankhatDataForGiver();
                        fetchData = FetchGahankhatForGiverData(Convert.ToInt32(mutationgiverIDs[i]));
                        //fetchData = FetchGahankhatInfoForTaker(Convert.ToInt32(mutationgiverIDs[i]));
                        if (fetchData != null)
                        {
                            mutationgiver.Add(fetchData);
                        }
                    }
                }

            }
            //HakkaSod Nond
            else if (applicationDTL.mutation_type_code == "09")
            {
                if (applicationDTL != null && !string.IsNullOrEmpty(applicationDTL.mutationgiverIDs))
                {
                    string[] mutationgiverIDs = applicationDTL.mutationgiverIDs.Split(",");

                    if (mutationgiverIDs.Length > 0)
                    {
                        for (int i = 0; i < mutationgiverIDs.Length; i++)
                        {
                            FetchHakkasodForGiverData fetchData = new FetchHakkasodForGiverData();
                            fetchData = FetchHakkasodInfoForGiver(Convert.ToInt32(mutationgiverIDs[i]));
                            if (fetchData != null)
                            {
                                mutationgiver.Add(fetchData);
                            }
                        }
                    }
                }
            }
            //Bhadepatta
            else if (applicationDTL.mutation_type_code == "10")
            {
                if (applicationDTL != null && !string.IsNullOrEmpty(applicationDTL.mutationgiverIDs))
                {
                    string[] mutationgiverIDs = applicationDTL.mutationgiverIDs.Split(",");

                    if (mutationgiverIDs.Length > 0)
                    {
                        for (int i = 0; i < mutationgiverIDs.Length; i++)
                        {
                            FetchBhadepattaData fetchData = new FetchBhadepattaData();
                            fetchData = FetchBhadepattaGiver(Convert.ToInt32(mutationgiverIDs[i])).GetAwaiter().GetResult();
                            if (fetchData != null)
                            {
                                mutationgiver.Add(fetchData);
                            }
                        }
                    }
                }
            }
            //Akumai Nond
            else if (applicationDTL.mutation_type_code == "20")
            {
                if (applicationDTL != null && !string.IsNullOrEmpty(applicationDTL.mutationgiverIDs))
                {
                    string[] mutationgiverIDs = applicationDTL.mutationgiverIDs.Split(",");

                    if (mutationgiverIDs.Length > 0)
                    {
                        for (int i = 0; i < mutationgiverIDs.Length; i++)
                        {
                            FetchAkumaiNondDataForGiver fetchData = new FetchAkumaiNondDataForGiver();
                            fetchData = FetchAkumaiNondInformationDataForGiver(Convert.ToInt32(mutationgiverIDs[i]));
                            if (fetchData != null)
                            {
                                mutationgiver.Add(fetchData);
                            }
                        }
                    }
                }
            }
            return mutationgiver;
        }
