        public FetchUploadedDocuments uploadDocuments(string nabhu, string applicationid)
        {
            FetchUploadedDocuments document = new FetchUploadedDocuments();
            var docname = _contextR.uploadedDocumentsDTLs.Where(a => a.city_servey_no == nabhu).Select(a => a.document_name).ToList();
            document.applicationID = applicationid;
            document.nabhuno = nabhu;
            document.docName = String.Join(",", docname);
            return document;
        }


        public ApplicationData GetApplicationDetailsonInwardNoClick(string applicationid)
        {
            ApplicationData application = new ApplicationData();

            //Fetch All Application Details
            ApplicationDTL applicationDTL = applicationServices.FetchApplicationData(applicationid);
            int userid = applicationDTL!.userMaster!.userid;

            // Fetch Registered User Data
            FetchUserData userData = new FetchUserData();
            userData = userServices.FetchUserData(userid);
            application.registereduser = userData;

            int mutationCode = Convert.ToInt32(applicationDTL.mutation_type_code);

            //Get Application Details
            application.applicationDtl = GetApplicationDtls(applicationDTL);

            //Get All Applicant Details
            List<FetchApplicantsData> applicantsList = new List<FetchApplicantsData>();
            if (applicationDTL != null && !string.IsNullOrEmpty(applicationDTL.applicantIDs))
            {
                string[] applicantIDS = applicationDTL.applicantIDs.Split(",");

                if (applicantIDS.Length > 0)
                {
                    for (int i = 0; i < applicantIDS.Length; i++)
                    {
                        FetchApplicantsData applicant = new FetchApplicantsData();
                        applicant = applicationServices.FetchApplicantData(Convert.ToInt32(applicantIDS[i]));
                        if (applicant != null)
                        {
                            applicantsList.Add(applicant);
                        }
                    }
                }
            }
            application.applicants = applicantsList;

            //Get All Mutation CTS Data
            List<FetchMutationCTSNoData> mutationCTSNoList = new List<FetchMutationCTSNoData>();
            if (applicationDTL != null && !string.IsNullOrEmpty(applicationDTL.mutation_cts_nos))
            {
                string[] mutationCTSNoIDs = applicationDTL.mutation_cts_nos.Split(",");

                FetchMutationCTSNoData mutationCTSNoData = new FetchMutationCTSNoData();
                if (mutationCTSNoIDs.Length > 0)
                {
                    for (int i = 0; i < mutationCTSNoIDs.Length; i++)
                    {
                        mutationCTSNoData = applicationServices.FetchMutationCTSData(Convert.ToInt32(mutationCTSNoIDs[i]));
                        if (mutationCTSNoData != null)
                        {
                            mutationCTSNoList.Add(mutationCTSNoData);
                        }
                    }
                }
                //CheckMutationCTSNoError(mutationCTSNoList, mutationCode);
            }
            application.mutationCTSNoData = mutationCTSNoList;



            //Get All Dast information
            List<FetchDastInformationData> fetchDastInformationList = new List<FetchDastInformationData>();
            if (applicationDTL != null && !string.IsNullOrEmpty(applicationDTL.dastIDs))
            {
                string[] dastIDs = applicationDTL.dastIDs.Split(",");
                if (dastIDs.Length > 0)
                {
                    for (int i = 0; i < dastIDs.Length; i++)
                    {
                        FetchDastInformationData fetchDastInformationData = new FetchDastInformationData();
                        fetchDastInformationData = applicationServices.FetchDastInformationData(Convert.ToInt32(dastIDs[i]));
                        if (fetchDastInformationData != null)
                        {
                            fetchDastInformationList.Add(fetchDastInformationData);
                        }
                    }

                }
            }
            //Checkdast(fetchDastInformationList, mutationCode);
            application.dastInformation = fetchDastInformationList;

            //Get All courtClaim
            List<FetchCourtClaimInformationData> fetchCourtClaimInformationList = new List<FetchCourtClaimInformationData>();
            if (applicationDTL!.Is_the_claim_pending_before_the_court == true)
            {
                if (applicationDTL != null && !string.IsNullOrEmpty(applicationDTL.courtClaimIDs))
                {
                    string[] courtClaimIDS = applicationDTL.courtClaimIDs.Split(",");
                    if (courtClaimIDS.Length > 0)
                    {
                        for (int i = 0; i < courtClaimIDS.Length; i++)
                        {
                            FetchCourtClaimInformationData fetchCourtClaimInformationData = new FetchCourtClaimInformationData();
                            fetchCourtClaimInformationData = applicationServices.FetchCourtClaimInformation(Convert.ToInt32(courtClaimIDS[i]));
                            if (fetchCourtClaimInformationData != null)
                            {
                                fetchCourtClaimInformationList.Add(fetchCourtClaimInformationData);
                            }
                        }
                    }
                }
            }
            application.courtClaimInformation = fetchCourtClaimInformationList;

            //Get Power of Attorney Giver & Taker

            List<POADTL> poa = new List<POADTL>();
            if (applicationDTL!.do_you_have_power_of_attorney == true)
            {
                ////Giver
                //if (applicationDTL != null && !string.IsNullOrEmpty(applicationDTL.powerOfAttorneyIDs))
                //{
                //    string[] powerOfAttorneyIDS = applicationDTL.powerOfAttorneyIDs.Split(",");

                //    if (powerOfAttorneyIDS.Length > 0)
                //    {
                //        for (int i = 0; i < powerOfAttorneyIDS.Length; i++)
                //        {
                //            FetchPOAForGiverData fetchPowerOfAttorneyInformationData = new FetchPOAForGiverData();
                //            fetchPowerOfAttorneyInformationData = applicationServices.FetchPowerOfAttorneyInfoForGiver(Convert.ToInt32(powerOfAttorneyIDS[i]));
                //            if (fetchPowerOfAttorneyInformationData != null)
                //            {
                //                fetchPowerOfAttorneyGiverInformationList.Add(fetchPowerOfAttorneyInformationData);
                //            }
                //        }
                //    }
                //}
                //Taker
                if (applicationDTL != null && !string.IsNullOrEmpty(applicationDTL.powerOfAttorneyIDs))
                {
                    string[] powerOfAttorneyIDS = applicationDTL.powerOfAttorneyIDs.Split(",");
                    if (powerOfAttorneyIDS.Length > 0)
                    {
                        for (int i = 0; i < powerOfAttorneyIDS.Length; i++)
                        {
                            POADTL finalPOADTL = new POADTL();
                            FetchPOAForTakerData fetchPowerOfAttorneyInformationData = new FetchPOAForTakerData();
                            List<FetchPOAForTakerData> fetchPowerOfAttorneyInformationList = new List<FetchPOAForTakerData>();
                            fetchPowerOfAttorneyInformationData = applicationServices.FetchPowerOfAttorneyInfoForTaker(Convert.ToInt32(powerOfAttorneyIDS[i]));
                            if (fetchPowerOfAttorneyInformationData != null && !string.IsNullOrEmpty(fetchPowerOfAttorneyInformationData.poa_giver_ids))
                            {
                                string[] poa_giver_ids = fetchPowerOfAttorneyInformationData.poa_giver_ids!.Split(",");
                                List<FetchGiverDataForPOA> giverDataList = new List<FetchGiverDataForPOA>();
                                if (!string.IsNullOrEmpty(fetchPowerOfAttorneyInformationData.poa_giver_ids))
                                {
                                    List<FetchPOAForGiverData> fetchPowerOfAttorneyGiverInformationList = new List<FetchPOAForGiverData>();
                                    for (int k = 0; k < poa_giver_ids.Length; k++)
                                    {
                                        FetchPOAForGiverData fetchPOAGiverDTL = new FetchPOAForGiverData();
                                        fetchPOAGiverDTL = applicationServices.FetchPowerOfAttorneyInfoForGiver(Convert.ToInt32(poa_giver_ids[k]));
                                        if (fetchPOAGiverDTL != null)
                                        {
                                            fetchPowerOfAttorneyGiverInformationList.Add(fetchPOAGiverDTL);
                                        }
                                        FetchGiverDataForPOA fetchGiverData = new FetchGiverDataForPOA();
                                        fetchGiverData = applicationServices.FetchPOAGiverDataByID(Convert.ToInt32(poa_giver_ids[k]));
                                        if (fetchGiverData != null)
                                        {
                                            giverDataList.Add(fetchGiverData);
                                        }
                                    }
                                    finalPOADTL.poAForGiver = fetchPowerOfAttorneyGiverInformationList;

                                    for (int j = 0; j < giverDataList.Count; j++)
                                    {
                                        if (j == 0)
                                        {
                                            fetchPowerOfAttorneyInformationData.giver_name_in_marathi = giverDataList[j].giver_names_in_marathi;
                                            fetchPowerOfAttorneyInformationData.giver_name_in_english = giverDataList[j].giver_names_in_english!;
                                        }
                                        else
                                        {
                                            fetchPowerOfAttorneyInformationData.giver_name_in_marathi = fetchPowerOfAttorneyInformationData.giver_name_in_marathi + ", " + giverDataList[j].giver_names_in_marathi;
                                            fetchPowerOfAttorneyInformationData.giver_name_in_english = fetchPowerOfAttorneyInformationData.giver_name_in_english + ", " + giverDataList[j].giver_names_in_english!;
                                        }
                                    }
                                    fetchPowerOfAttorneyInformationList.Add(fetchPowerOfAttorneyInformationData);
                                }
                                finalPOADTL.poAForTaker = fetchPowerOfAttorneyInformationList;
                            }
                            if (finalPOADTL.poAForGiver != null && finalPOADTL.poAForTaker != null)
                            {
                                poa.Add(finalPOADTL);
                            }
                        }
                        //FetchGiverData fetchGiverData = new FetchGiverData();
                        //fetchGiverData = applicationServices.FetchPOAGiverData(applicationid);
                        //for (int i = 0; i < powerOfAttorneyIDS.Length; i++)
                        //{
                        //    FetchPOAForTakerData fetchPowerOfAttorneyInformationData = new FetchPOAForTakerData();
                        //    fetchPowerOfAttorneyInformationData = applicationServices.FetchPowerOfAttorneyInfoForTaker(Convert.ToInt32(powerOfAttorneyIDS[i]));
                        //    if (fetchPowerOfAttorneyInformationData != null)
                        //    {
                        //        if (fetchGiverData != null)
                        //        {
                        //            for (int j = 0; j < fetchGiverData.giver_names_in_marathi!.Count; j++)
                        //            {
                        //                if (j == 0)
                        //                {
                        //                    fetchPowerOfAttorneyInformationData.giver_name_in_marathi = fetchGiverData.giver_names_in_marathi[j];
                        //                    fetchPowerOfAttorneyInformationData.giver_name_in_english = fetchGiverData.giver_names_in_english![j];
                        //                }
                        //                else
                        //                {
                        //                    fetchPowerOfAttorneyInformationData.giver_name_in_marathi = fetchPowerOfAttorneyInformationData.giver_name_in_marathi + ", " + fetchGiverData.giver_names_in_marathi[j];
                        //                    fetchPowerOfAttorneyInformationData.giver_name_in_english = fetchPowerOfAttorneyInformationData.giver_name_in_english + ", " + fetchGiverData.giver_names_in_english![j];
                        //                }
                        //            }
                        //        }
                        //        fetchPowerOfAttorneyInformationList.Add(fetchPowerOfAttorneyInformationData);
                        //    }
                        //}
                    }
                }

            }
            application.poa = poa;

            //application.poAForGiver = fetchPowerOfAttorneyGiverInformationList;
            //application.poAForTaker = fetchPowerOfAttorneyInformationList;

            //Get Mayat Data ,mrutyu dakhala and varas nond
            List<FetchMayatDetailsData> fetchmayatinfoList = new List<FetchMayatDetailsData>();
            List<FetchMrutuDakhalaDetailsData> fetchMrutyuDetails = new List<FetchMrutuDakhalaDetailsData>();
            List<FetchVarasNondDetailsData> fetchvarasNondList = new List<FetchVarasNondDetailsData>();
            if (applicationDTL!.mutation_type_code == "01")
            {
                if (!string.IsNullOrEmpty(applicationDTL.mayatIDs))
                {
                    string[] kharediNondIDs = applicationDTL.mayatIDs!.Split(",");

                    if (kharediNondIDs.Length > 0)
                    {
                        for (int i = 0; i < kharediNondIDs.Length; i++)
                        {
                            FetchMayatDetailsData fetchKharediNondGiverInformationData = new FetchMayatDetailsData();
                            fetchKharediNondGiverInformationData = FetchMayatDetails(Convert.ToInt32(kharediNondIDs[i]));
                            if (fetchKharediNondGiverInformationData != null)
                            {
                                fetchmayatinfoList.Add(fetchKharediNondGiverInformationData);
                            }
                            FetchMrutuDakhalaDetailsData fetchKharediNondGiverInformationData1 = new FetchMrutuDakhalaDetailsData();
                            fetchKharediNondGiverInformationData1 = FetchMrutuDakhalaDetails(Convert.ToInt32(kharediNondIDs[i]));
                            if (fetchKharediNondGiverInformationData1 != null)
                            {
                                fetchMrutyuDetails.Add(fetchKharediNondGiverInformationData1);
                            }
                        }

                    }
                }

                if (!string.IsNullOrEmpty(applicationDTL.varasIDS))
                {
                    string[] kharediNondIDs = applicationDTL.varasIDS.Split(",");

                    if (kharediNondIDs.Length > 0)
                    {
                        for (int i = 0; i < kharediNondIDs.Length; i++)
                        {
                            FetchVarasNondDetailsData fetchdata = new FetchVarasNondDetailsData();
                            fetchdata = FetchVarasData(Convert.ToInt32(kharediNondIDs[i]));
                            if (fetchdata != null)
                            {
                                fetchvarasNondList.Add(fetchdata);
                            }
                        }

                    }
                }
            }
            /*application.mayatData = fetchmayatinfoList;
            application.mrutuDakhalaDetailsData = fetchMrutyuDetails;
            application.varasNondDetailsData = fetchvarasNondList;*/
            string mutationgivertype = "";
            string mutationtakertype = "";
            string varasnond = "";
            if (applicationDTL.mutation_type_code == "01")
            {
                mutationgivertype = "मयताची माहिती";
                mutationtakertype = "मृत्यू दाखला माहिती";
                varasnond = "वारस नोंद माहिती";
            }
            else if (applicationDTL.mutation_type_code == "03")
            {
                mutationgivertype = "खरेदीनोंद देणार";
                mutationtakertype = "खरेदीनोंद घेणार";
            }
            //Bakshish Patra
            else if (applicationDTL.mutation_type_code == "04")
            {
                mutationgivertype = "बक्षीसपत्र देणार";
                mutationtakertype = "बक्षीसपत्र घेणार";
            }
            //Mrutyu Nond
            else if (applicationDTL.mutation_type_code == "05")
            {
                mutationgivertype = "मृत्यूपत्र/इच्छापत्र देणार";
                mutationtakertype = "मृत्यूपत्र/इच्छापत्र घेणार";
            }
            //Gahankhat Nond
            else if (applicationDTL.mutation_type_code == "06")
            {
                mutationgivertype = "गाहाणखत/तारण/बोजा देणार";
                mutationtakertype = "गाहाणखत/तारण/बोजा घेणार";

            }
            else if (applicationDTL.mutation_type_code == "07")
            {
                mutationgivertype = "गहाण खतानुसार तारण परत/ बोजा कमी करणे देणार";
                mutationtakertype = "गहाण खतानुसार तारण परत/ बोजा कमी करणे घेणार";

            }
            //HakkaSod Nond
            else if (applicationDTL.mutation_type_code == "09")
            {
                mutationgivertype = "हक्कसोड पत्र/रिलीज डिड देणार";
                mutationtakertype = "हक्कसोड पत्र/रिलीज डिड घेणार";
            }

            //Mutation Giver 
            List<dynamic> giver = mutationgiverData(applicationDTL);
            //Mutation Taker
            List<dynamic> taker = mutationtakerData(applicationDTL);

            List<MutationList> mutation = new List<MutationList>();
            if (applicationDTL.mutation_type_code == "01")
            {
                mutation.Add(new MutationList { type = mutationgivertype, value = fetchmayatinfoList });
                mutation.Add(new MutationList { type = mutationtakertype, value = fetchMrutyuDetails });
                mutation.Add(new MutationList { type = varasnond, value = fetchvarasNondList });
            }
            else
            {
                mutation.Add(new MutationList { type = mutationgivertype, value = giver });
                mutation.Add(new MutationList { type = mutationtakertype, value = taker });
            }

            application.Mutation = mutation;
            //Document Data

            var nabhuNoList = _context.mutationCTSNoDTLs.Include(app => app.applicationDTL).Where(app => app.applicationDTL!.applicationid == applicationid).Select(a => a.selected_city_servey_no).ToList();
            //string nabh  = String.Join(", ", nabhuNoList);
            List<FetchUploadedDocuments> document = new List<FetchUploadedDocuments>();
            foreach (string? nabhu in nabhuNoList)
            {
                var data = uploadDocuments(nabhu!, applicationid);
                if (data != null)
                {
                    document.Add(data);
                }
            }
            application.uploaded = document;

            List<FetchUploadedDocumentData> fetchUploadedDocumentsList = new List<FetchUploadedDocumentData>();
            if (applicationDTL != null && !string.IsNullOrEmpty(applicationDTL.uploadedDocIDs))
            {
                string[] uploadedDocIDs = applicationDTL.uploadedDocIDs.Split(",");

                if (uploadedDocIDs.Length > 0)
                {
                    for (int i = 0; i < uploadedDocIDs.Length; i++)
                    {
                        FetchUploadedDocumentData fetchUploadedDocumentsData = new FetchUploadedDocumentData();
                        fetchUploadedDocumentsData = FetchUploadedDocumentDTLs(Convert.ToInt32(uploadedDocIDs[i]));
                        if (fetchUploadedDocumentsData != null)
                        {
                            fetchUploadedDocumentsList.Add(fetchUploadedDocumentsData);
                        }
                    }
                }
            }
            application.uploadedDocument = fetchUploadedDocumentsList;

            return application;

        }

