        public string SaveBhadepattaGiverData(BhadepattaGiverInputModel bhadepattaGiver)
        {
            MutationGiverTakerDTL dbTable = new MutationGiverTakerDTL();
            MutationGiverTakerDTL fetchData = new MutationGiverTakerDTL();
            TextInfo textInfo = new CultureInfo("en-US", false).TextInfo;
            MethodForFileUpload methodForFile = new MethodForFileUpload();
            using (var scope = new TransactionScope())
            {
                try
                {
                    if (bhadepattaGiver.userDetails != null && !string.IsNullOrEmpty(bhadepattaGiver.userDetails.firstName))
                    {
                        if (string.IsNullOrEmpty(bhadepattaGiver.userDetails.nabhu))
                        {
                            return "Please select अर्जामधील न.भू.क्र.";
                        }

                        if (string.IsNullOrEmpty(bhadepattaGiver.userDetails!.firstNameEng!))
                        {
                            return "Please Enter First Name in भाडेपट्टा धारक (इंग्रजी मध्ये)";
                        }
                        if (string.IsNullOrEmpty(bhadepattaGiver.areaOfMutation!.actualArea!))
                        {
                            return "Please wait, मिळकत पत्रिके प्रमाणे क्षेत्र (चौ.मी.) is not fetched.";
                        }
                        if (methodForFile.ContainsSpecialCharactersInMarathiName(bhadepattaGiver.userDetails!.aliceName!))
                        {
                            return "देणाऱ्याचे उर्फ नाव (मराठी मध्ये) Field contains English Letter / special characters!";
                        }
                        if (methodForFile.ContainsSpecialCharactersInName(bhadepattaGiver.userDetails!.motherNameEng!))
                        {
                            return "आईचे नाव (इंग्रजी मध्ये) Field contains special characters / Numbers!";
                        }
                        if (methodForFile.ContainsSpecialCharactersInMarathiName(bhadepattaGiver.userDetails!.motherName!))
                        {
                            return "आईचे नाव (मराठी मध्ये) Field contains English Letters / special characters / Numbers!";
                        }
                        //if (methodForFile.CheckKArea(bhadepattaGiver.areaForMutation!.actualArea!))
                        //{
                        //    return "मिळकत पत्रिके प्रमाणे क्षेत्र (चौ.मी.) field contains special character / please enter 10 digit मिळकत पत्रिके प्रमाणे क्षेत्र (चौ.मी.)";
                        //}
                        if (!string.IsNullOrEmpty(bhadepattaGiver.areaOfMutation!.mutationArea!) && methodForFile.CheckKArea(bhadepattaGiver.areaOfMutation!.mutationArea!))
                        {
                            return "भाडेपट्टा देणाऱ्याच्या नावे क्षेत्र (चौ.मी.) field contains special character / please enter 10 digit ";
                        }

                        string FolderPath = @"\\10.10.248.2\pde_propertycard\MUTATIONDOCS\" + bhadepattaGiver.applicationid + @"\GIVER";
                        //string FolderPath = @"D:\WWW\MUTATIONDOCS\" + bhadepattaGiver.applicationid + @"\GIVER";
                        // Assign Values to Model
                        KharediNondModel kharediNondModel = new KharediNondModel();
                        UserMaster userMaster = _context.userMasters.FirstOrDefault(s => s.userid == bhadepattaGiver.userid!)!;
                        kharediNondModel.userMaster = userMaster;

                        fetchData = _context.mutationDTL.Include(app => app.applicationDTL).Where(data => data.applicationDTL!.applicationid!.Equals(bhadepattaGiver.applicationid)
                        && data.owner_village_code == bhadepattaGiver.village_code!
                        && data.cts_number == bhadepattaGiver.ctsNo
                        && data.mutation_srno == bhadepattaGiver.mutationSroNo
                        && data.owner_number == bhadepattaGiver.ownerNo
                        && data.isTaker == 0
                        && data.isDeleted == false).FirstOrDefault()!;


                        if (fetchData != null)
                        {

                            kharediNondModel.owner_village_code = bhadepattaGiver.village_code;
                            kharediNondModel.ctsNo = bhadepattaGiver.ctsNo;
                            kharediNondModel.mutationSroNo = bhadepattaGiver.mutationSroNo;
                            kharediNondModel.ownerNo = bhadepattaGiver.ownerNo;


                            string nabhu = System.Text.RegularExpressions.Regex.Replace(bhadepattaGiver.userDetails!.nabhu!, @"\s*\(.*?\)", "").Trim();
                            MutationCTSNoDTL mutation = _context.mutationCTSNoDTLs.FirstOrDefault(s => s.selected_city_servey_no == nabhu && s.applicationDTL!.applicationid == bhadepattaGiver.applicationid)!;
                            kharediNondModel.mutation_cts_no_id = mutation.mutation_cts_no_id;

                            ApplicationDTL applicationDTL = _context.applicationDTL.FirstOrDefault(s => s.applicationid == bhadepattaGiver.applicationid!)!;
                            kharediNondModel.applicationDTL = applicationDTL;

                            PropertyTypeMaster proptype = _context.propertyTypes.FirstOrDefault(s => s.propertytypeid == Convert.ToInt32("0"))!;
                            kharediNondModel.propType = proptype;

                            kharediNondModel.address_type = bhadepattaGiver.address!.addressType!.Trim().ToUpper();
                            if (kharediNondModel.address_type == "INDIA")
                            {
                                if (string.IsNullOrEmpty(bhadepattaGiver.address!.indiaAddress!.plotNo))
                                {
                                    return "Please enter सदनिका / घर /प्लॉट नं.";
                                }
                                if (string.IsNullOrEmpty(bhadepattaGiver.address!.indiaAddress!.impSymbol))
                                {
                                    return "Please enter महत्त्वाची खूण";
                                }
                                if (string.IsNullOrEmpty(bhadepattaGiver.address!.indiaAddress!.pincode))
                                {
                                    return "Please enter पिन कोड";
                                }
                                if (!string.IsNullOrEmpty(bhadepattaGiver.address!.indiaAddress!.pincode) && methodForFile.CheckPinCode(bhadepattaGiver.address!.indiaAddress!.pincode))
                                {
                                    if (string.IsNullOrEmpty(bhadepattaGiver.address!.indiaAddress!.postOfficeName))
                                    {
                                        return "Please select Post Office Name / Enter correct Pin Code.";
                                    }
                                    return "पिन कोड field contains special characters";
                                }

                                if (methodForFile.CheckIndianAddress(bhadepattaGiver.address!.indiaAddress!.plotNo))
                                {
                                    return "सदनिका / घर /प्लॉट नं. field contains special characters";
                                }
                                if (!string.IsNullOrEmpty(bhadepattaGiver.address!.indiaAddress!.building!) && methodForFile.CheckIndianAddress(bhadepattaGiver.address!.indiaAddress!.building!))
                                {
                                    return "इमारत (बिल्डिंग)/सोसायटी क्रमांक किंवा नाव field contains special characters";
                                }
                                if (!string.IsNullOrEmpty(bhadepattaGiver.address!.indiaAddress!.mainRoad!) && methodForFile.CheckIndianAddress(bhadepattaGiver.address!.indiaAddress!.mainRoad!))
                                {
                                    return "मुख्य रस्ता field contains special characters";
                                }
                                if (methodForFile.CheckIndianAddress(bhadepattaGiver.address!.indiaAddress!.impSymbol!))
                                {
                                    return "महत्त्वाची खूण field contains special characters";
                                }
                                if (!string.IsNullOrEmpty(bhadepattaGiver.address!.indiaAddress!.area!) && methodForFile.CheckIndianAddress(bhadepattaGiver.address!.indiaAddress!.area!))
                                {
                                    return "महत्त्वाची खूण field contains special characters";
                                }
                                if (!string.IsNullOrEmpty(bhadepattaGiver.address!.indiaAddress!.mobile!) && methodForFile.CheckMobNo(bhadepattaGiver.address!.indiaAddress!.mobile!))
                                {
                                    return "मोबाईल field contains special characters";
                                }
                                //if (methodForFile.CheckPinCode(bhadepattaGiver.address!.indiaAddress!.pincode!))
                                //{
                                //    return "पिन कोड field contains special characters";
                                //}

                                kharediNondModel.mobileno = bhadepattaGiver.address.indiaAddress!.mobile;
                                kharediNondModel.mobilenoverified = bhadepattaGiver.address.indiaAddress.mobileOTP;
                                kharediNondModel.emailid = "NA";
                                kharediNondModel.emailidverified = "NA";

                                kharediNondModel.address = "NA";
                                kharediNondModel.state = bhadepattaGiver.address.indiaAddress.state;
                                kharediNondModel.district = bhadepattaGiver.address.indiaAddress.district;
                                kharediNondModel.taluka = bhadepattaGiver.address.indiaAddress.taluka;
                                kharediNondModel.city = bhadepattaGiver.address.indiaAddress.city;
                                kharediNondModel.plotno = bhadepattaGiver.address.indiaAddress.plotNo;
                                kharediNondModel.building = bhadepattaGiver.address.indiaAddress.building;
                                kharediNondModel.mainroad = bhadepattaGiver.address.indiaAddress.mainRoad;
                                kharediNondModel.impSymbol = bhadepattaGiver.address.indiaAddress.impSymbol;
                                kharediNondModel.area = bhadepattaGiver.address.indiaAddress.area;
                                kharediNondModel.pincode = bhadepattaGiver.address.indiaAddress.pincode;
                                kharediNondModel.post_office_name = bhadepattaGiver.address.indiaAddress.postOfficeName;
                                kharediNondModel.address_proof_name = bhadepattaGiver.address.indiaAddress.addressProofName;
                                kharediNondModel.address_proof_src = bhadepattaGiver.address.indiaAddress.addressProofSrc == "" ? "NA" : bhadepattaGiver.address.indiaAddress.addressProofSrc!;
                                kharediNondModel.signature_name = bhadepattaGiver.address.indiaAddress.signatureName == "" ? "NA" : bhadepattaGiver.address.indiaAddress.signatureName;
                                kharediNondModel.signature_src = bhadepattaGiver.address.indiaAddress.signatureSrc == "" ? "NA" : bhadepattaGiver.address.indiaAddress.signatureSrc!;
                            }
                            else if (kharediNondModel.address_type == "FOREIGN")
                            {
                                if (string.IsNullOrEmpty(bhadepattaGiver.address.foreignAddress!.address) || string.IsNullOrEmpty(bhadepattaGiver.address.foreignAddress!.email))
                                {
                                    return "पत्ता and ई मेल field is mandatory";
                                }
                                if (methodForFile.CheckForeignAddress(bhadepattaGiver.address.foreignAddress!.address))
                                {
                                    return "पत्ता field contains special characters";
                                }
                                if (methodForFile.CheckEmail(bhadepattaGiver.address.foreignAddress!.email))
                                {
                                    return "ई मेल field contains special characters";
                                }

                                kharediNondModel.address = bhadepattaGiver.address.foreignAddress!.address;
                                kharediNondModel.mobileno = bhadepattaGiver.address.foreignAddress.mobile;
                                kharediNondModel.emailid = bhadepattaGiver.address.foreignAddress.email;
                                kharediNondModel.emailidverified = bhadepattaGiver.address.foreignAddress.emailOTP;
                                kharediNondModel.signature_name = bhadepattaGiver.address.foreignAddress.signatureName;
                                //kharediNondModel.signature_src = bhadepattaGiver.address.foreignAddress!.signatureSrc == "" ? null : Convert.FromBase64String(bhadepattaGiver.address.foreignAddress.signatureSrc!.Split(",")[1]);

                                kharediNondModel.state = "NA";
                                kharediNondModel.district = "NA";
                                kharediNondModel.taluka = "NA";
                                kharediNondModel.city = "NA";
                                kharediNondModel.plotno = "NA";
                                kharediNondModel.building = "NA";
                                kharediNondModel.mainroad = "NA";
                                kharediNondModel.impSymbol = "NA";
                                kharediNondModel.area = "NA";
                                kharediNondModel.pincode = "NA";
                                kharediNondModel.post_office_name = "NA";
                                kharediNondModel.address_proof_name = "NA";
                                kharediNondModel.address_proof_src = "NA";
                                //kharediNondModel.signature_name = bhadepattaGiver.address.foreignAddress.signatureName;
                            }
                            kharediNondModel.prefixcode_marathi = bhadepattaGiver.userDetails!.suffixcode;
                            kharediNondModel.prefixcode_eng = bhadepattaGiver.userDetails.suffixCodeEng;
                            kharediNondModel.prefix_in_eng = bhadepattaGiver.userDetails!.suffixEng;
                            kharediNondModel.fname_in_eng = bhadepattaGiver.userDetails.firstNameEng;
                            kharediNondModel.mname_in_eng = bhadepattaGiver.userDetails.middleNameEng;
