        public async Task<FetchBhadepattaData> FetchBhadepattaGiver(int mutationdtlid)
        {
            try
            {
                MethodForFileUpload methodForFile = new MethodForFileUpload();
                MutationGiverTakerDTL mutationGiver = new MutationGiverTakerDTL();
                mutationGiver = await _ICommonRepository.GetMutationDtlData(mutationdtlid);

                FetchBhadepattaData fetchBhadepattaData = new FetchBhadepattaData();

                var returnData = _mapper.Map<FetchBhadepattaData>(mutationGiver);

                returnData.mutation_dtl_id = mutationGiver!.mutation_givertaker_id;
                returnData.fullNameInMarathi = commonFunctions.ReplaceNA(mutationGiver.fname_in_marathi!.Trim())
                    + " " + commonFunctions.ReplaceNA(mutationGiver.mname_in_marathi!.Trim()) + " " +
                    commonFunctions.ReplaceNA(mutationGiver.lname_in_marathi!.Trim());
                returnData.fullNameInEng = commonFunctions.ReplaceNA(mutationGiver.fname_in_eng!.Trim()) + " " +
                    commonFunctions.ReplaceNA(mutationGiver.mname_in_eng!.Trim()) + " " +
                    commonFunctions.ReplaceNA(mutationGiver.lname_in_eng!.Trim());

                if (mutationGiver.address_proof_document_path != "NA")
                {
                    string AddressProofExt = Path.GetExtension(mutationGiver.address_proof_document_path)!;
                    string AddressProof = methodForFile.ConvertImageToBase64(mutationGiver.address_proof_document_path!);
                    mutationGiver.address_proof_document_path = string.IsNullOrEmpty(AddressProof) ? "NA" : "data:image/" + AddressProofExt.Replace(".", "") + ";base64," + AddressProof;
                    returnData.address!.indiaAddress!.addressProofSrc = mutationGiver.address_proof_document_path;
                }
                else
                {
                    returnData.address!.indiaAddress!.addressProofName = mutationGiver.address_proof_document_name;
                    returnData.address!.indiaAddress!.addressProofSrc = mutationGiver.address_proof_document_path;
                }

                return returnData;
            }
            catch (Exception ex)
            {
                throw new HandleException(ex.Message.ToString());
            }
        }

