        public FetchBhadepattaInfoData FetchBhadepattaInfoData(string applicationid)
        {
            try
            {
                MethodForFileUpload methodForFile = new MethodForFileUpload();
                BhadepattaInfoDtl bhadepattaInfoDtl = new BhadepattaInfoDtl();
                FetchBhadepattaInfoData fetchBhadepattaInfoData = new FetchBhadepattaInfoData();
                bhadepattaInfoDtl = _contextR.bhadepattaInfoDtl.Where(a => a.applicationid!.Equals(applicationid) && a.isDeleted == false).FirstOrDefault()!;
                if (bhadepattaInfoDtl != null)
                {
                    fetchBhadepattaInfoData.applicationid = bhadepattaInfoDtl.applicationid;
                    fetchBhadepattaInfoData.Info_id = bhadepattaInfoDtl.Info_id;
                    fetchBhadepattaInfoData.bhadepattaTenureYear = bhadepattaInfoDtl.bhadepattaTenureYear;
                    fetchBhadepattaInfoData.bhadepattaTenureMonth = bhadepattaInfoDtl.bhadepattaTenureMonth;
                    fetchBhadepattaInfoData.bhadepattaFromDate = bhadepattaInfoDtl.bhadepattaFromDate;
                    fetchBhadepattaInfoData.bhadepattaToDate = bhadepattaInfoDtl.bhadepattaToDate;
                    fetchBhadepattaInfoData.bhadepattaAmount = bhadepattaInfoDtl.bhadepattaAmount;
                    return fetchBhadepattaInfoData;
                }
                else
                {
                    fetchBhadepattaInfoData = null;
                    return fetchBhadepattaInfoData;
                }
               
            }
            catch (Exception ex)
            {
                throw new HandleException(ex.Message.ToString());
            }
        }

        public string DeleteBhadepattaInfo(DeleteBhadepattaInfo deleteBhadepattaInfo)
        {
            using (var scope = new TransactionScope(TransactionScopeAsyncFlowOption.Enabled))
            {
                try
                {
                    var entity = _context.bhadepattaInfoDtl.FirstOrDefault(s => s.Info_id == deleteBhadepattaInfo.info_id! && s.isDeleted == false)!;
                    if (entity != null)
                    {
                        entity.isDeleted = true;
                        entity.deletedDateTime = DateTime.UtcNow;
                        _context.bhadepattaInfoDtl.Attach(entity);
                        _context.SaveChanges();
                        //var res = await _ICommonRepository.UpdateEntityValues(entity);
                        //if (res.ToLower() == "update")
                        //{
                        //    scope.Complete();
                        //    return "Success";
                        //}
                        //else
                        //{
                        //    return "false";

                        //}
                    }
                    scope.Complete();
                    return "Success";
                    //else { return "false"; }
                }
                catch (Exception ex)
                {
                    throw new HandleException(ex.Message.ToString());
                }
            }
        }

