        public string SaveBhadepattaTakerData(BhadepattaTakerInputModel BhadepattaTakerData)
        {
            TextInfo textInfo = new CultureInfo("en-US", false).TextInfo;
            MethodForFileUpload methodForFile = new MethodForFileUpload();
            MutationGiverTakerDTL dbTable = new MutationGiverTakerDTL();
            using (var scope = new TransactionScope())
            {
                try
                {
                    string FolderPath = @"\\10.10.248.2\pde_propertycard\MUTATIONDOCS\" + BhadepattaTakerData.applicationid + @"\TAKER";
                    //string FolderPath = @"D:\WWW\MUTATIONDOCS\" + BhadepattaTakerData.applicationid + @"\TAKER";
                    // Assign Values to Model
                    KharediNondModel kharediNondModel = new KharediNondModel();
                    UserMaster userMaster = _context.userMasters.FirstOrDefault(s => s.userid == BhadepattaTakerData.userid!)!;
                    kharediNondModel.userMaster = userMaster;

                    ApplicationDTL applicationDTL = _context.applicationDTL.FirstOrDefault(s => s.applicationid == BhadepattaTakerData.applicationid!)!;
                    kharediNondModel.applicationDTL = applicationDTL;

                    PropertyTypeMaster proptype = _context.propertyTypes.FirstOrDefault(s => s.propertytypeid == Convert.ToInt32(BhadepattaTakerData.isMHProperty!.propType!))!;
                    kharediNondModel.propType = proptype;

                    kharediNondModel.address_type = BhadepattaTakerData.address!.addressType!.Trim().ToUpper();
                    if (kharediNondModel.address_type == "INDIA")
                    {
                        if (string.IsNullOrEmpty(BhadepattaTakerData.address!.indiaAddress!.plotNo))
                        {
                            return "Please enter सदनिका / घर /प्लॉट नं.";
                        }
                        if (string.IsNullOrEmpty(BhadepattaTakerData.address!.indiaAddress!.impSymbol))
                        {
                            return "Please enter महत्त्वाची खूण";
                        }
                        if (string.IsNullOrEmpty(BhadepattaTakerData.address!.indiaAddress!.pincode))
                        {
                            return "Please enter पिन कोड";
                        }
                        if (!string.IsNullOrEmpty(BhadepattaTakerData.address!.indiaAddress!.pincode) && methodForFile.CheckPinCode(BhadepattaTakerData.address!.indiaAddress!.pincode))
                        {
                            if (string.IsNullOrEmpty(BhadepattaTakerData.address!.indiaAddress!.postOfficeName))
                            {
                                return "Please select Post Office Name / Enter correct Pin Code.";
                            }
                            return "पिन कोड field contains special characters";
                        }

                        if (methodForFile.CheckIndianAddress(BhadepattaTakerData.address!.indiaAddress!.plotNo))
                        {
                            return "सदनिका / घर /प्लॉट नं. field contains special characters";
                        }
                        if (!string.IsNullOrEmpty(BhadepattaTakerData.address!.indiaAddress!.building!) && methodForFile.CheckIndianAddress(BhadepattaTakerData.address!.indiaAddress!.building!))
                        {
                            return "इमारत (बिल्डिंग)/सोसायटी क्रमांक किंवा नाव field contains special characters";
                        }
                        if (!string.IsNullOrEmpty(BhadepattaTakerData.address!.indiaAddress!.mainRoad!) && methodForFile.CheckIndianAddress(BhadepattaTakerData.address!.indiaAddress!.mainRoad!))
                        {
                            return "मुख्य रस्ता field contains special characters";
                        }
                        if (methodForFile.CheckIndianAddress(BhadepattaTakerData.address!.indiaAddress!.impSymbol!))
                        {
                            return "महत्त्वाची खूण field contains special characters";
                        }
