        public async Task<FetchBhadepattaData> FetchBhadepattaTaker(int mutationdtlid)
        {
            try
            {
                MethodForFileUpload methodForFile = new MethodForFileUpload();
                MutationGiverTakerDTL mutationTaker = new MutationGiverTakerDTL();
                mutationTaker = await _ICommonRepository.GetMutationDtlData(mutationdtlid);

                FetchBhadepattaData fetchBhadepattaData = new FetchBhadepattaData();

                var returnData = _mapper.Map<FetchBhadepattaData>(mutationTaker);

                returnData.mutation_dtl_id = mutationTaker.mutation_givertaker_id;
                if (returnData.usertype_code == 1)
                {
                    returnData.fullNameInMarathi = commonFunctions.ReplaceNA(mutationTaker.fname_in_marathi!.Trim())
                   + " " + commonFunctions.ReplaceNA(mutationTaker.mname_in_marathi!.Trim()) + " " +
                   commonFunctions.ReplaceNA(mutationTaker.lname_in_marathi!.Trim());
                    returnData.fullNameInEng = commonFunctions.ReplaceNA(mutationTaker.fname_in_eng!.Trim()) + " " +
                        commonFunctions.ReplaceNA(mutationTaker.mname_in_eng!.Trim()) + " " +
                        commonFunctions.ReplaceNA(mutationTaker.lname_in_eng!.Trim());

                }
                else
                {
                    returnData.fullNameInMarathi = commonFunctions.ReplaceNA(mutationTaker.company_name_in_marathi!.Trim());
                    returnData.fullNameInEng = commonFunctions.ReplaceNA(mutationTaker.company_name_in_eng!.Trim());
                }


                if (mutationTaker.address_proof_document_path != "NA")
                {
                    string AddressProofExt = Path.GetExtension(mutationTaker.address_proof_document_path)!;
                    string AddressProof = methodForFile.ConvertImageToBase64(mutationTaker.address_proof_document_path!);
                    mutationTaker.address_proof_document_path = string.IsNullOrEmpty(AddressProof) ? "NA" : "data:image/" + AddressProofExt.Replace(".", "") + ";base64," + AddressProof;
                    returnData.address!.indiaAddress!.addressProofSrc = mutationTaker.address_proof_document_path;
                }
                else
                {
                    returnData.address!.indiaAddress!.addressProofName = mutationTaker.address_proof_document_name;
                    returnData.address!.indiaAddress!.addressProofSrc = mutationTaker.address_proof_document_path;
                }

                return returnData;
            }
            catch (Exception ex)
            {
                throw new HandleException(ex.Message.ToString());
            }
        }

        public string SaveBhadepattaInfoData(BhadepattaInfoInputModel bhadepattaInfoInputModel)
        {
            BhadepattaInfoDtl bhadepattaInfoDtl = new BhadepattaInfoDtl();
            //model;
            BhadepattaInfoModel bhadepattaInfoModel = new BhadepattaInfoModel();

            TextInfo textInfo = new CultureInfo("en-US", false).TextInfo;
            MethodForFileUpload methodForFile = new MethodForFileUpload();
            using (var scope = new TransactionScope())
            {
                try
                {
                    if (bhadepattaInfoInputModel.leasePeriod!.ToUpper() == "NO")
                    {
                        if (string.IsNullOrEmpty(bhadepattaInfoInputModel.bhadepattaTenureYear) || string.IsNullOrEmpty(bhadepattaInfoInputModel.bhadepattaTenureMonth) ||
                        Convert.ToDateTime(bhadepattaInfoInputModel.bhadepattaFromDate) == DateTime.MinValue || Convert.ToDateTime(bhadepattaInfoInputModel.bhadepattaToDate) == DateTime.MinValue || string.IsNullOrEmpty(bhadepattaInfoInputModel.bhadepattaAmount))
                        //  if (string.IsNullOrEmpty(bhadepattaInfoInputModel.bhadepattaTenureYear) || string.IsNullOrEmpty(bhadepattaInfoInputModel.bhadepattaTenureMonth) ||
                        //bhadepattaInfoInputModel.bhadepattaFromDate == DateTime.MinValue || bhadepattaInfoInputModel.bhadepattaToDate == DateTime.MinValue || string.IsNullOrEmpty(bhadepattaInfoInputModel.bhadepattaAmount))
                        {
                            return "Please Check all Fields";
                        }
                        else
                        {
                            bool checkDuplicateEntry = _context.bhadepattaInfoDtl.Any(x => x.applicationid == bhadepattaInfoInputModel.applicationid && x.isDeleted == false);
                            //_context.bhadepattaInfoDtl.Any(a => a.applicationid.Equals(bhadepattaInfoInputModel.applicationid) &&  a.isDeleted == false).FirstOrDefault()!;
