        public string SaveMrutyuPatraTaker(MrutyuPatraDataForTaker takerData)
        {
            using (var scope = new TransactionScope())
            {
                MethodForFileUpload methodForFile = new MethodForFileUpload();
                MutationGiverTakerDTL dbTable = new MutationGiverTakerDTL();
                UploadedDocumentsDTL uploadedDocumentsDTL = new UploadedDocumentsDTL();

                TextInfo textInfo = new CultureInfo("en-US", false).TextInfo;
                string FolderPath = @"\\10.10.248.2\pde_propertycard\MUTATIONDOCS\" + takerData.applicationid + @"\TAKER";
                //string FolderPath = @"D:\WWW\MUTATIONDOCS\" + takerData.applicationid + @"\TAKER";
                try
                {

                    // Assign values to model
                    MrutyuPatraModel dataModel = new MrutyuPatraModel();
                    dataModel.usertype_code = takerData.usertype_code;
                    dataModel.usertype = takerData.usertype!.Trim().ToUpper();
                    dataModel.passport_name = takerData.photo!.passportName;

                    dataModel.owner_of_property_in_maharashtra = takerData.isMHProperty!.hasProperty!.Trim().ToUpper();
                    PropertyTypeMaster proptype = _context.propertyTypes.FirstOrDefault(s => s.propertytypeid == Convert.ToInt32(takerData.isMHProperty.propType))!;
                    dataModel.propType = proptype;

                    UserMaster userMaster = _context.userMasters.FirstOrDefault(s => s.userid == takerData.userid)!;
                    dataModel.userMaster = userMaster;

                    ApplicationDTL applicationDTL = _context.applicationDTL.FirstOrDefault(s => s.applicationid == takerData.applicationid)!;
                    dataModel.applicationDTL = applicationDTL;

                    //MutationCTSNoDTL mutation = _context.mutationCTSNoDTLs.FirstOrDefault(s => s.selected_city_servey_no == nabhu && s.applicationDTL!.applicationid == takerData.applicationid)!;

                    MutationGiverTakerDTL fetchMutationTakerData = new MutationGiverTakerDTL();

                    if (dataModel.owner_of_property_in_maharashtra.Trim().ToUpper() == "YES")
                    {
                        if (dataModel.propType.propertytypeid == 1 && string.IsNullOrEmpty(takerData.isMHProperty.userDetails!.khataNo))
                        {
                            return "When Property Type Is 7/12 Then Khate No Should Not Be Empty";
                        }
                        if (dataModel.propType.propertytypeid == 2 && string.IsNullOrEmpty(takerData.isMHProperty.userDetails!.naBhu))
                        {
                            return "When Property Type Is Property Card Then City Servey No Should Not Be Empty";
