        public FetchMrutyuPatraForTakerData FetchMrutyuPatraForTakerData(int mutationGiverID)
        {
            try
            {
                MethodForFileUpload methodForFile = new MethodForFileUpload();
                MutationGiverTakerDTL mutationGiverTakerDTL = new MutationGiverTakerDTL();
                mutationGiverTakerDTL = _contextR.mutationDTL.Include(i => i.userMaster).Include(app => app.applicationDTL).Include(proptype => proptype.prop_type).Where(data => data.mutation_givertaker_id.Equals(mutationGiverID) && data.isDeleted == false).FirstOrDefault()!;

                FetchMrutyuPatraForTakerData fetchData = new FetchMrutyuPatraForTakerData();
                fetchData.mutation_dtl_id = mutationGiverTakerDTL.mutation_givertaker_id;
                fetchData.userid = mutationGiverTakerDTL.userMaster!.userid;
                fetchData.applicationid = mutationGiverTakerDTL.applicationDTL!.applicationid;
                fetchData.usertype_code = mutationGiverTakerDTL.user_type_code;
                fetchData.userType = mutationGiverTakerDTL.user_type;
                fetchData.mobileNo = mutationGiverTakerDTL.mobileno;

                //Photo Details
                PhotoData photo = new PhotoData();
                photo.passportName = mutationGiverTakerDTL.profile_pic_file_name;
                photo.passportSrc = mutationGiverTakerDTL.profile_pic_file_path;
                //string PhotoProofExt = Path.GetExtension(mutationGiverTakerDTL.profile_pic_file_path)!;
                //string PhotoProof = methodForFile.ConvertImageToBase64(mutationGiverTakerDTL.profile_pic_file_path!);
                //mutationGiverTakerDTL.profile_pic_file_path = string.IsNullOrEmpty(PhotoProof) ? "NA" : "data:image/" + PhotoProofExt.Replace(".", "") + ";base64," + PhotoProof;
                photo.passportSrc = mutationGiverTakerDTL.profile_pic_file_path;
                fetchData.photo = photo;

                //isMHDetails
                isMHPropertyForMrutyuPatraTaker isMHproperty = new isMHPropertyForMrutyuPatraTaker();
                isMHproperty.hasProperty = mutationGiverTakerDTL.has_property;
                isMHproperty.propType = mutationGiverTakerDTL.prop_type!.propertytype;


                MrutyuPatraTakeruserDetails takeruserDetails = new MrutyuPatraTakeruserDetails();
                takeruserDetails!.suffix = mutationGiverTakerDTL.prefix_in_marathi;
                takeruserDetails.firstName = mutationGiverTakerDTL.fname_in_marathi;
                takeruserDetails.middleName = mutationGiverTakerDTL.mname_in_marathi;
                takeruserDetails.lastName = mutationGiverTakerDTL.lname_in_marathi;
                takeruserDetails.suffixEng = mutationGiverTakerDTL.prefix_in_eng;
                takeruserDetails.firstNameEng = mutationGiverTakerDTL.fname_in_eng;
                takeruserDetails.middleNameEng = mutationGiverTakerDTL.mname_in_eng;
                takeruserDetails.lastNameEng = mutationGiverTakerDTL.lname_in_eng;
                takeruserDetails.companyName = mutationGiverTakerDTL.company_name_in_marathi!;
                takeruserDetails.companyNameEng = mutationGiverTakerDTL.company_name_in_eng!;
                takeruserDetails.khataNo = mutationGiverTakerDTL.khatano;
                takeruserDetails.naBhu = mutationGiverTakerDTL.city_servey_no;
                takeruserDetails.ulpin = mutationGiverTakerDTL.ulpin;
                takeruserDetails.userName = mutationGiverTakerDTL.userName;

                DistrictData district = new DistrictData();
                district.district_code = mutationGiverTakerDTL.district_code;
                district.district_name = mutationGiverTakerDTL.district_name_in_marathi;
                district.district_english_name = mutationGiverTakerDTL.district_name_in_eng;
                takeruserDetails.district = district;

                TalukaData taluka = new TalukaData();
                taluka.office_code = mutationGiverTakerDTL.ofc_code;
                taluka.office_name = mutationGiverTakerDTL.ofc_name;
                takeruserDetails.taluka = taluka;

                VillageData village = new VillageData();
                village.village_code = mutationGiverTakerDTL.village_code;
                village.village_name = mutationGiverTakerDTL.village_name;
                takeruserDetails.village = village;

                isMHproperty.userDetails = takeruserDetails;
                fetchData.isMHProperty = isMHproperty;

                //Dharak Details
                DharakDTLForMrutyuPatraTaker dharak = new DharakDTLForMrutyuPatraTaker();
                UserdharakDetailsForMrutyuPatraTaker userdharak = new UserdharakDetailsForMrutyuPatraTaker();
                Gender gender = new Gender();

                if (mutationGiverTakerDTL.user_type_code == 1)
                {
                    //fetchData.fullNameInMarathi = mutationGiverTakerDTL.fname_in_marathi!.Trim() + " " + mutationGiverTakerDTL.mname_in_marathi!.Trim() + " " + mutationGiverTakerDTL.lname_in_marathi!.Trim();
